window.DIALOGUE_BANK = [{"id": "dA1-1", "level": "A1", "title": "Ordering at a Cafe", "titlePt": "Pedindo num café", "setting": "Uma cliente pede café e algo para comer no balcão de uma cafeteria.", "speakers": [{"name": "Emma", "g": "f"}, {"name": "Tom", "g": "m"}], "lines": [{"s": 1, "en": "Hi there! What can I get you?", "pt": "Oi! O que vai querer?"}, {"s": 0, "en": "Hi! Can I get a small coffee, please?", "pt": "Oi! Pode me ver um café pequeno, por favor?"}, {"s": 1, "en": "Sure. Hot or iced?", "pt": "Claro. Quente ou gelado?"}, {"s": 0, "en": "Iced, please. It's really hot today.", "pt": "Gelado, por favor. Está muito quente hoje."}, {"s": 1, "en": "Good idea. Anything to eat?", "pt": "Boa ideia. Algo para comer?"}, {"s": 0, "en": "Yes, a chocolate muffin. How much is that?", "pt": "Sim, um muffin de chocolate. Quanto fica?"}, {"s": 1, "en": "That's six fifty. For here or to go?", "pt": "Fica seis e cinquenta. Para comer aqui ou para viagem?"}, {"s": 0, "en": "To go, thanks. I'm in a hurry.", "pt": "Para viagem, obrigada. Estou com pressa."}], "questions": [{"q": "Que tipo de café a cliente pede?", "options": ["Um café gelado pequeno", "Um café quente grande", "Um café com leite médio"], "answer": 0}, {"q": "Quanto ela paga no total?", "options": ["Cinco e cinquenta", "Seis e quinze", "Seis e cinquenta"], "answer": 2}, {"q": "Por que ela pede para viagem?", "options": ["Porque a cafeteria está cheia", "Porque está com pressa", "Porque vai levar para uma amiga"], "answer": 1}]}, {"id": "dA1-2", "level": "A1", "title": "Asking for Directions", "titlePt": "Pedindo informação", "setting": "Um turista pergunta a uma moradora como chegar a um museu.", "speakers": [{"name": "Ben", "g": "m"}, {"name": "Lucy", "g": "f"}], "lines": [{"s": 0, "en": "Excuse me, is the art museum near here?", "pt": "Com licença, o museu de arte fica perto daqui?"}, {"s": 1, "en": "Yes, it's pretty close. About ten minutes on foot.", "pt": "Sim, é bem perto. Uns dez minutos a pé."}, {"s": 0, "en": "Great. How do I get there?", "pt": "Ótimo. Como eu chego lá?"}, {"s": 1, "en": "Go straight and turn left at the bank.", "pt": "Siga reto e vire à esquerda no banco."}, {"s": 0, "en": "Left at the bank. Okay.", "pt": "À esquerda no banco. Certo."}, {"s": 1, "en": "Then it's on your right, next to a big park.", "pt": "Depois fica à sua direita, ao lado de um parque grande."}, {"s": 0, "en": "Thank you so much!", "pt": "Muito obrigado!"}, {"s": 1, "en": "No problem. Enjoy the museum!", "pt": "De nada. Aproveite o museu!"}], "questions": [{"q": "Quanto tempo leva para chegar ao museu a pé?", "options": ["Cinco minutos", "Dez minutos", "Vinte minutos"], "answer": 1}, {"q": "Onde ele deve virar à esquerda?", "options": ["No banco", "Na farmácia", "No parque"], "answer": 0}, {"q": "O que fica ao lado do museu?", "options": ["Um banco", "Uma estação de metrô", "Um parque grande"], "answer": 2}]}, {"id": "dA1-3", "level": "A1", "title": "Meeting a New Neighbor", "titlePt": "Conhecendo um vizinho novo", "setting": "Dois vizinhos se conhecem no corredor do prédio.", "speakers": [{"name": "Sarah", "g": "f"}, {"name": "Mike", "g": "m"}], "lines": [{"s": 0, "en": "Hi! Are you new in the building?", "pt": "Oi! Você é novo no prédio?"}, {"s": 1, "en": "Yes, I just moved in. I'm in apartment 4B.", "pt": "Sim, acabei de me mudar. Estou no apartamento 4B."}, {"s": 0, "en": "Welcome! I'm right across the hall, in 4C.", "pt": "Bem-vindo! Eu moro bem em frente, no 4C."}, {"s": 1, "en": "Nice to meet you. Where are you from?", "pt": "Prazer em te conhecer. De onde você é?"}, {"s": 0, "en": "I'm from Chicago. What about you?", "pt": "Sou de Chicago. E você?"}, {"s": 1, "en": "I'm from Texas. I work at the hospital down the street.", "pt": "Sou do Texas. Trabalho no hospital aqui na rua."}, {"s": 0, "en": "Oh, cool! Let me know if you need anything.", "pt": "Ah, que legal! Me avisa se precisar de alguma coisa."}], "questions": [{"q": "Em qual apartamento o homem mora?", "options": ["4C", "4A", "4B"], "answer": 2}, {"q": "De onde a mulher é?", "options": ["De Chicago", "Do Texas", "De Nova York"], "answer": 0}, {"q": "Onde o homem trabalha?", "options": ["Numa escola", "No hospital da rua", "Num banco"], "answer": 1}]}, {"id": "dA1-4", "level": "A1", "title": "Buying a T-shirt", "titlePt": "Comprando uma camiseta", "setting": "Um cliente procura uma camiseta numa loja de roupas.", "speakers": [{"name": "Jack", "g": "m"}, {"name": "Anna", "g": "f"}], "lines": [{"s": 1, "en": "Hi! Can I help you?", "pt": "Oi! Posso ajudar?"}, {"s": 0, "en": "Yes, please. I'm looking for a T-shirt.", "pt": "Sim, por favor. Estou procurando uma camiseta."}, {"s": 1, "en": "What size are you?", "pt": "Qual é o seu tamanho?"}, {"s": 0, "en": "Medium, I think. Do you have this one in blue?", "pt": "Médio, eu acho. Vocês têm esta em azul?"}, {"s": 1, "en": "Yes, here you go. The fitting room is over there.", "pt": "Sim, aqui está. O provador é ali."}, {"s": 0, "en": "Thanks. It fits great! How much is it?", "pt": "Obrigado. Ficou ótima! Quanto custa?"}, {"s": 1, "en": "It's twenty dollars, but it's on sale today. Fifteen.", "pt": "São vinte dólares, mas está em promoção hoje. Quinze."}, {"s": 0, "en": "Perfect. I'll take it.", "pt": "Perfeito. Vou levar."}], "questions": [{"q": "Que cor de camiseta ele quer?", "options": ["Preta", "Azul", "Branca"], "answer": 1}, {"q": "Qual é o tamanho dele?", "options": ["Pequeno", "Grande", "Médio"], "answer": 2}, {"q": "Quanto ele paga pela camiseta hoje?", "options": ["Quinze dólares", "Vinte dólares", "Doze dólares"], "answer": 0}]}, {"id": "dA1-5", "level": "A1", "title": "At the Supermarket", "titlePt": "No supermercado", "setting": "Uma cliente pede ajuda a um funcionário para achar produtos no supermercado.", "speakers": [{"name": "Kate", "g": "f"}, {"name": "Sam", "g": "m"}], "lines": [{"s": 0, "en": "Excuse me, where can I find the eggs?", "pt": "Com licença, onde eu encontro os ovos?"}, {"s": 1, "en": "They're in aisle six, next to the milk.", "pt": "Estão no corredor seis, ao lado do leite."}, {"s": 0, "en": "Thanks. And do you have fresh bread?", "pt": "Obrigada. E vocês têm pão fresco?"}, {"s": 1, "en": "Yes, the bakery is at the back of the store.", "pt": "Sim, a padaria fica no fundo da loja."}, {"s": 0, "en": "Great. Are you open on Sundays?", "pt": "Ótimo. Vocês abrem aos domingos?"}, {"s": 1, "en": "Yes, from eight to eight, every day.", "pt": "Sim, das oito às oito, todos os dias."}, {"s": 0, "en": "Perfect. Thanks for your help!", "pt": "Perfeito. Obrigada pela ajuda!"}], "questions": [{"q": "Em que corredor ficam os ovos?", "options": ["Corredor três", "Corredor nove", "Corredor seis"], "answer": 2}, {"q": "Onde fica a padaria?", "options": ["No fundo da loja", "Perto da entrada", "Ao lado do caixa"], "answer": 0}, {"q": "Qual é o horário da loja aos domingos?", "options": ["Fechada aos domingos", "Das oito às oito", "Das nove às seis"], "answer": 1}]}, {"id": "dA1-6", "level": "A1", "title": "Weekend Plans", "titlePt": "Planos para o fim de semana", "setting": "Dois amigos conversam por telefone e combinam um programa no sábado.", "speakers": [{"name": "Leo", "g": "m"}, {"name": "Mia", "g": "f"}], "lines": [{"s": 0, "en": "Hey Mia! What are you doing on Saturday?", "pt": "E aí, Mia! O que você vai fazer no sábado?"}, {"s": 1, "en": "Nothing much. Why?", "pt": "Nada de mais. Por quê?"}, {"s": 0, "en": "Do you want to see a movie with me?", "pt": "Quer ver um filme comigo?"}, {"s": 1, "en": "Sure! What time?", "pt": "Claro! Que horas?"}, {"s": 0, "en": "There's a show at seven. We can get pizza before.", "pt": "Tem uma sessão às sete. Dá para comer pizza antes."}, {"s": 1, "en": "Sounds great. Can we meet at the theater at six?", "pt": "Parece ótimo. A gente pode se encontrar no cinema às seis?"}, {"s": 0, "en": "Perfect. See you then!", "pt": "Perfeito. Até lá!"}], "questions": [{"q": "O que ele convida a amiga para fazer?", "options": ["Ir a um show", "Ver um filme", "Jantar na casa dele"], "answer": 1}, {"q": "A que horas começa a sessão?", "options": ["Às sete", "Às seis", "Às oito"], "answer": 0}, {"q": "Onde eles vão se encontrar?", "options": ["Na pizzaria", "Na casa dela", "No cinema"], "answer": 2}]}, {"id": "dA1-7", "level": "A1", "title": "Joining a Gym", "titlePt": "Matrícula na academia", "setting": "Uma pessoa pergunta sobre planos e horários numa academia.", "speakers": [{"name": "Olivia", "g": "f"}, {"name": "Dan", "g": "m"}], "lines": [{"s": 1, "en": "Hi, welcome! How can I help you?", "pt": "Oi, bem-vinda! Como posso ajudar?"}, {"s": 0, "en": "Hi! I want to join the gym. How much is it?", "pt": "Oi! Quero me matricular na academia. Quanto custa?"}, {"s": 1, "en": "It's thirty dollars a month.", "pt": "São trinta dólares por mês."}, {"s": 0, "en": "Okay. What time do you open?", "pt": "Certo. Que horas vocês abrem?"}, {"s": 1, "en": "We open at six in the morning and close at ten.", "pt": "Abrimos às seis da manhã e fechamos às dez."}, {"s": 0, "en": "Great. I usually work out before work.", "pt": "Ótimo. Eu costumo treinar antes do trabalho."}, {"s": 1, "en": "Do you want to try a free class today?", "pt": "Quer experimentar uma aula grátis hoje?"}, {"s": 0, "en": "Yes, I'd love that!", "pt": "Sim, adoraria!"}], "questions": [{"q": "Quanto custa a academia por mês?", "options": ["Vinte dólares", "Quarenta dólares", "Trinta dólares"], "answer": 2}, {"q": "Quando ela costuma treinar?", "options": ["Antes do trabalho", "Na hora do almoço", "À noite"], "answer": 0}, {"q": "O que o funcionário oferece a ela?", "options": ["Um desconto", "Uma aula grátis", "Uma garrafa de água"], "answer": 1}]}, {"id": "dA1-8", "level": "A1", "title": "At the Pharmacy", "titlePt": "Na farmácia", "setting": "Um cliente com dor de cabeça pede um remédio ao farmacêutico.", "speakers": [{"name": "Chris", "g": "m"}, {"name": "Grace", "g": "f"}], "lines": [{"s": 1, "en": "Good afternoon. Can I help you?", "pt": "Boa tarde. Posso ajudar?"}, {"s": 0, "en": "Yes, I have a bad headache. Can you help me?", "pt": "Sim, estou com uma dor de cabeça forte. Pode me ajudar?"}, {"s": 1, "en": "Sure. Do you have a fever?", "pt": "Claro. Você está com febre?"}, {"s": 0, "en": "No, I don't. I'm just really tired.", "pt": "Não. Só estou muito cansado."}, {"s": 1, "en": "Okay, take these pills. One every six hours.", "pt": "Certo, tome estes comprimidos. Um a cada seis horas."}, {"s": 0, "en": "Can I take them with coffee?", "pt": "Posso tomar com café?"}, {"s": 1, "en": "Better with water. And get some rest!", "pt": "Melhor com água. E descanse um pouco!"}, {"s": 0, "en": "Thanks. I will.", "pt": "Obrigado. Vou descansar."}], "questions": [{"q": "Qual é o problema do homem?", "options": ["Dor de garganta", "Dor de cabeça", "Febre alta"], "answer": 1}, {"q": "De quanto em quanto tempo ele deve tomar o comprimido?", "options": ["A cada seis horas", "A cada quatro horas", "Uma vez por dia"], "answer": 0}, {"q": "Com o que a farmacêutica recomenda tomar o remédio?", "options": ["Com café", "Com suco", "Com água"], "answer": 2}]}, {"id": "dA2-1", "level": "A2", "title": "Hotel Check-in", "titlePt": "Check-in no hotel", "setting": "Um hóspede chega ao hotel depois de uma longa viagem e faz o check-in.", "speakers": [{"name": "Paul", "g": "m"}, {"name": "Rachel", "g": "f"}], "lines": [{"s": 1, "en": "Good evening! Welcome to the hotel. Do you have a reservation?", "pt": "Boa noite! Bem-vindo ao hotel. O senhor tem reserva?"}, {"s": 0, "en": "Yes, it's under Paul Carter. Three nights.", "pt": "Sim, está no nome de Paul Carter. Três noites."}, {"s": 1, "en": "Here it is. Could I see your ID, please?", "pt": "Aqui está. Posso ver seu documento, por favor?"}, {"s": 0, "en": "Sure. Is breakfast included?", "pt": "Claro. O café da manhã está incluso?"}, {"s": 1, "en": "Yes, it's served from seven to ten in the restaurant.", "pt": "Sim, é servido das sete às dez no restaurante."}, {"s": 0, "en": "Great. Would it be possible to get a quieter room? I'm a light sleeper.", "pt": "Ótimo. Seria possível um quarto mais silencioso? Tenho sono leve."}, {"s": 1, "en": "No problem. I'll put you on the eighth floor, away from the street.", "pt": "Sem problema. Vou colocar o senhor no oitavo andar, longe da rua."}, {"s": 0, "en": "Thanks a lot. And what's the Wi-Fi password?", "pt": "Muito obrigado. E qual é a senha do Wi-Fi?"}, {"s": 1, "en": "It's on your key card. Enjoy your stay!", "pt": "Está no seu cartão-chave. Aproveite a estadia!"}], "questions": [{"q": "Por quantas noites ele vai ficar?", "options": ["Duas", "Três", "Cinco"], "answer": 1}, {"q": "Por que ele pede um quarto mais silencioso?", "options": ["Porque tem sono leve", "Porque vai trabalhar no quarto", "Porque está com o filho pequeno"], "answer": 0}, {"q": "Onde está a senha do Wi-Fi?", "options": ["Na recepção", "No quarto, perto da TV", "No cartão-chave"], "answer": 2}]}, {"id": "dA2-2", "level": "A2", "title": "Booking a Doctor's Appointment", "titlePt": "Marcando consulta médica", "setting": "Uma paciente liga para o consultório para marcar uma consulta.", "speakers": [{"name": "Laura", "g": "f"}, {"name": "Kevin", "g": "m"}], "lines": [{"s": 1, "en": "Good morning, Green Valley Clinic. How can I help you?", "pt": "Bom dia, Clínica Green Valley. Como posso ajudar?"}, {"s": 0, "en": "Hi, I'd like to make an appointment with Dr. Lee, please.", "pt": "Oi, eu gostaria de marcar uma consulta com a Dra. Lee, por favor."}, {"s": 1, "en": "Sure. Is it urgent?", "pt": "Claro. É urgente?"}, {"s": 0, "en": "Not really. I've had a sore throat since last week.", "pt": "Não muito. Estou com dor de garganta desde a semana passada."}, {"s": 1, "en": "Okay. She's free on Thursday at two thirty or Friday at nine.", "pt": "Certo. Ela tem horário na quinta às duas e meia ou na sexta às nove."}, {"s": 0, "en": "Friday morning is better for me. I work late on Thursdays.", "pt": "Sexta de manhã é melhor para mim. Eu trabalho até tarde às quintas."}, {"s": 1, "en": "Perfect. Could you arrive ten minutes early to fill out a form?", "pt": "Perfeito. Você poderia chegar dez minutos antes para preencher um formulário?"}, {"s": 0, "en": "Of course. Do I need to bring anything?", "pt": "Claro. Preciso levar alguma coisa?"}, {"s": 1, "en": "Just your insurance card. See you on Friday!", "pt": "Só a sua carteirinha do convênio. Até sexta!"}], "questions": [{"q": "Qual é o problema de saúde da paciente?", "options": ["Dor nas costas", "Febre", "Dor de garganta"], "answer": 2}, {"q": "Qual horário ela escolhe?", "options": ["Sexta às nove", "Quinta às duas e meia", "Sexta às duas"], "answer": 0}, {"q": "Por que ela deve chegar mais cedo?", "options": ["Para fazer exames", "Para preencher um formulário", "Para pagar a consulta"], "answer": 1}]}, {"id": "dA2-3", "level": "A2", "title": "At the Airport", "titlePt": "No aeroporto", "setting": "Um passageiro despacha a mala e descobre um atraso no voo.", "speakers": [{"name": "Daniel", "g": "m"}, {"name": "Megan", "g": "f"}], "lines": [{"s": 1, "en": "Hi, where are you flying today?", "pt": "Oi, para onde o senhor vai voar hoje?"}, {"s": 0, "en": "To Miami. Here's my passport.", "pt": "Para Miami. Aqui está meu passaporte."}, {"s": 1, "en": "Thanks. Are you checking any bags?", "pt": "Obrigada. Vai despachar alguma mala?"}, {"s": 0, "en": "Just this one. I think it's a bit heavy.", "pt": "Só esta. Acho que está um pouco pesada."}, {"s": 1, "en": "Let's see... it's twenty-five kilos. Sorry, the limit is twenty-three.", "pt": "Vamos ver... tem vinte e cinco quilos. Desculpe, o limite é vinte e três."}, {"s": 0, "en": "Oh no. Can I take something out and put it in my backpack?", "pt": "Ah, não. Posso tirar alguma coisa e colocar na mochila?"}, {"s": 1, "en": "Sure, go ahead. Also, your flight is delayed by one hour.", "pt": "Claro, fique à vontade. Além disso, seu voo está atrasado uma hora."}, {"s": 0, "en": "Really? So what time are we boarding?", "pt": "Sério? Então que horas vamos embarcar?"}, {"s": 1, "en": "At four fifteen, from gate twelve.", "pt": "Às quatro e quinze, no portão doze."}], "questions": [{"q": "Qual é o problema com a mala dele?", "options": ["Está danificada", "Está dois quilos acima do limite", "É grande demais para o avião"], "answer": 1}, {"q": "O que ele decide fazer?", "options": ["Pagar uma taxa extra", "Deixar a mala no aeroporto", "Passar algumas coisas para a mochila"], "answer": 2}, {"q": "A que horas e em qual portão ele vai embarcar?", "options": ["Às quatro e quinze, portão doze", "Às três e quinze, portão doze", "Às quatro e quinze, portão vinte"], "answer": 0}]}, {"id": "dA2-4", "level": "A2", "title": "A Busy Day at Work", "titlePt": "Um dia corrido no trabalho", "setting": "Dois colegas de trabalho conversam sobre uma reunião e um relatório.", "speakers": [{"name": "Rebecca", "g": "f"}, {"name": "Mark", "g": "m"}], "lines": [{"s": 1, "en": "Hey, did you see the email about the meeting?", "pt": "Ei, você viu o e-mail sobre a reunião?"}, {"s": 0, "en": "Yeah, they moved it to three o'clock, right?", "pt": "Vi, mudaram para as três, né?"}, {"s": 1, "en": "Right. But I'm going to be late. I have a call with a client at two thirty.", "pt": "Isso. Mas eu vou me atrasar. Tenho uma ligação com um cliente às duas e meia."}, {"s": 0, "en": "No worries. I'll take notes for you.", "pt": "Tranquilo. Eu faço anotações para você."}, {"s": 1, "en": "Thanks, I owe you one. Did you finish the sales report?", "pt": "Valeu, fico te devendo essa. Você terminou o relatório de vendas?"}, {"s": 0, "en": "Almost. It's taking longer than I expected.", "pt": "Quase. Está demorando mais do que eu esperava."}, {"s": 1, "en": "Do you need a hand with it?", "pt": "Precisa de uma ajuda?"}, {"s": 0, "en": "Actually, yes. Could you check the numbers for March?", "pt": "Na verdade, sim. Você poderia conferir os números de março?"}, {"s": 1, "en": "Sure, send it over and I'll take a look after lunch.", "pt": "Claro, me manda e eu dou uma olhada depois do almoço."}], "questions": [{"q": "Por que ele vai se atrasar para a reunião?", "options": ["Vai almoçar com o chefe", "Tem uma ligação com um cliente", "Tem uma consulta médica"], "answer": 1}, {"q": "O que ela oferece fazer na reunião?", "options": ["Fazer anotações para ele", "Apresentar o relatório", "Remarcar a reunião"], "answer": 0}, {"q": "Que parte do relatório ele vai conferir?", "options": ["Os números de janeiro", "Os gráficos finais", "Os números de março"], "answer": 2}]}, {"id": "dA2-5", "level": "A2", "title": "Renting an Apartment", "titlePt": "Alugando um apartamento", "setting": "Uma pessoa visita um apartamento para alugar e conversa com o proprietário.", "speakers": [{"name": "Jessica", "g": "f"}, {"name": "Ryan", "g": "m"}], "lines": [{"s": 1, "en": "So, this is the living room. It gets a lot of sun in the morning.", "pt": "Então, esta é a sala. Bate bastante sol de manhã."}, {"s": 0, "en": "It's really nice. It's bigger than my place now.", "pt": "É muito bonita. É maior do que o lugar onde moro agora."}, {"s": 1, "en": "And there are two bedrooms and one bathroom.", "pt": "E tem dois quartos e um banheiro."}, {"s": 0, "en": "How much is the rent?", "pt": "Quanto é o aluguel?"}, {"s": 1, "en": "It's fourteen hundred a month. Water is included, but not electricity.", "pt": "São mil e quatrocentos por mês. A água está incluída, mas a luz não."}, {"s": 0, "en": "Okay. Are pets allowed? I have a small cat.", "pt": "Certo. Pode ter animais? Eu tenho um gato pequeno."}, {"s": 1, "en": "Cats are fine, but no dogs, sorry.", "pt": "Gato pode, mas cachorro não, desculpe."}, {"s": 0, "en": "Great. I really like it. Can I let you know by Monday?", "pt": "Ótimo. Gostei muito. Posso te dar uma resposta até segunda?"}, {"s": 1, "en": "Sure, but other people are interested, so don't wait too long.", "pt": "Claro, mas tem outras pessoas interessadas, então não demore muito."}], "questions": [{"q": "Quanto é o aluguel por mês?", "options": ["Mil e quatrocentos", "Mil e duzentos", "Quatrocentos"], "answer": 0}, {"q": "O que está incluído no aluguel?", "options": ["A luz", "A água", "A internet"], "answer": 1}, {"q": "Que animal ela tem?", "options": ["Um cachorro pequeno", "Um passarinho", "Um gato pequeno"], "answer": 2}]}, {"id": "dA2-6", "level": "A2", "title": "A Problem at the Restaurant", "titlePt": "Um problema no restaurante", "setting": "Um cliente reclama educadamente do prato que recebeu.", "speakers": [{"name": "Eric", "g": "m"}, {"name": "Nicole", "g": "f"}], "lines": [{"s": 1, "en": "How is everything here?", "pt": "Está tudo bem por aqui?"}, {"s": 0, "en": "Actually, I'm sorry, but there's a problem with my order.", "pt": "Na verdade, desculpe, mas tem um problema com o meu pedido."}, {"s": 1, "en": "Oh, I'm sorry. What's wrong?", "pt": "Ah, sinto muito. O que houve?"}, {"s": 0, "en": "I ordered the chicken, but this is fish. And it's a little cold.", "pt": "Eu pedi o frango, mas isto é peixe. E está um pouco frio."}, {"s": 1, "en": "I'm so sorry about that. I'll bring you the chicken right away.", "pt": "Peço muitas desculpas. Vou trazer o frango agora mesmo."}, {"s": 0, "en": "Thanks. How long will it take?", "pt": "Obrigado. Quanto tempo vai demorar?"}, {"s": 1, "en": "About ten minutes. Can I get you a drink while you wait? It's on the house.", "pt": "Uns dez minutos. Posso trazer uma bebida enquanto espera? É por conta da casa."}, {"s": 0, "en": "That's very kind. A lemonade, please.", "pt": "Muita gentileza. Uma limonada, por favor."}, {"s": 1, "en": "Coming right up. And dessert is free tonight, too.", "pt": "Já trago. E a sobremesa hoje é cortesia também."}], "questions": [{"q": "Qual foi o problema com o pedido?", "options": ["Veio frango no lugar de peixe", "Veio peixe no lugar de frango", "Veio sem acompanhamento"], "answer": 1}, {"q": "Quanto tempo o cliente vai esperar pelo prato certo?", "options": ["Cerca de cinco minutos", "Cerca de vinte minutos", "Cerca de dez minutos"], "answer": 2}, {"q": "O que o restaurante oferece de cortesia?", "options": ["Uma bebida e a sobremesa", "Só o café", "Um desconto de dez por cento"], "answer": 0}]}, {"id": "dA2-7", "level": "A2", "title": "Lost Phone", "titlePt": "Celular perdido", "setting": "Uma passageira vai ao setor de achados e perdidos procurar o celular que esqueceu no ônibus.", "speakers": [{"name": "Hannah", "g": "f"}, {"name": "Greg", "g": "m"}], "lines": [{"s": 0, "en": "Hi, I think I left my phone on the bus yesterday.", "pt": "Oi, acho que deixei meu celular no ônibus ontem."}, {"s": 1, "en": "Okay, let's see. Which bus were you on?", "pt": "Certo, vamos ver. Em qual ônibus você estava?"}, {"s": 0, "en": "The number 22. I got off downtown around six p.m.", "pt": "O 22. Desci no centro por volta das seis da tarde."}, {"s": 1, "en": "What does your phone look like?", "pt": "Como é o seu celular?"}, {"s": 0, "en": "It's black, with a red case. The screen is a little broken.", "pt": "É preto, com uma capinha vermelha. A tela está um pouco quebrada."}, {"s": 1, "en": "Let me check... Is this it?", "pt": "Deixa eu ver... É este?"}, {"s": 0, "en": "Yes! That's it! Thank you so much. I was so worried.", "pt": "Sim! É esse! Muito obrigada. Eu estava tão preocupada."}, {"s": 1, "en": "No problem. I just need you to sign this form and show me some ID.", "pt": "Não há de quê. Só preciso que você assine este formulário e mostre um documento."}], "questions": [{"q": "Em qual ônibus ela perdeu o celular?", "options": ["No 12", "No 22", "No 32"], "answer": 1}, {"q": "Como é a capinha do celular dela?", "options": ["Vermelha", "Preta", "Azul"], "answer": 0}, {"q": "O que ela precisa fazer para pegar o celular?", "options": ["Pagar uma taxa", "Voltar amanhã", "Assinar um formulário e mostrar um documento"], "answer": 2}]}, {"id": "dA2-8", "level": "A2", "title": "Buying a Train Ticket", "titlePt": "Comprando passagem de trem", "setting": "Um viajante compra uma passagem de trem na bilheteria da estação.", "speakers": [{"name": "Andrew", "g": "m"}, {"name": "Julia", "g": "f"}], "lines": [{"s": 0, "en": "Hi, I'd like a ticket to Boston, please.", "pt": "Oi, eu queria uma passagem para Boston, por favor."}, {"s": 1, "en": "One way or round trip?", "pt": "Só ida ou ida e volta?"}, {"s": 0, "en": "Round trip. I'm coming back on Sunday.", "pt": "Ida e volta. Vou voltar no domingo."}, {"s": 1, "en": "The next train leaves at ten forty. It's the express, so it's faster but more expensive.", "pt": "O próximo trem sai às dez e quarenta. É o expresso, então é mais rápido, mas mais caro."}, {"s": 0, "en": "How much is it?", "pt": "Quanto custa?"}, {"s": 1, "en": "Ninety dollars. The regular train at eleven thirty is sixty.", "pt": "Noventa dólares. O trem comum das onze e meia custa sessenta."}, {"s": 0, "en": "I'm not in a rush, so I'll take the cheaper one.", "pt": "Não estou com pressa, então vou pegar o mais barato."}, {"s": 1, "en": "Good choice. It leaves from platform three.", "pt": "Boa escolha. Ele sai da plataforma três."}, {"s": 0, "en": "Thanks. Is there a place to get coffee nearby?", "pt": "Obrigado. Tem algum lugar para tomar café aqui perto?"}, {"s": 1, "en": "Yes, there's a cafe right next to the platform.", "pt": "Sim, tem um café bem ao lado da plataforma."}], "questions": [{"q": "Que tipo de passagem ele compra?", "options": ["Só ida", "Ida e volta", "Passe mensal"], "answer": 1}, {"q": "Qual trem ele escolhe e por quê?", "options": ["O expresso, porque é mais rápido", "O das onze e meia, porque está com pressa", "O das onze e meia, porque é mais barato"], "answer": 2}, {"q": "De qual plataforma sai o trem dele?", "options": ["Plataforma três", "Plataforma um", "Plataforma onze"], "answer": 0}]}, {"id": "dB1-1", "level": "B1", "title": "The Job Interview", "titlePt": "A entrevista de emprego", "setting": "Uma gerente entrevista um candidato para uma vaga de atendimento ao cliente em uma empresa de software.", "speakers": [{"name": "Laura", "g": "f"}, {"name": "Daniel", "g": "m"}], "lines": [{"s": 0, "en": "Thanks for coming in, Daniel. So, tell me a little about your experience.", "pt": "Obrigada por vir, Daniel. Então, me fale um pouco sobre a sua experiência."}, {"s": 1, "en": "Sure. I've worked in customer service for about four years, mostly at a hotel downtown.", "pt": "Claro. Trabalho com atendimento ao cliente há uns quatro anos, principalmente num hotel no centro."}, {"s": 0, "en": "Great. Why do you want to leave the hotel?", "pt": "Ótimo. Por que você quer sair do hotel?"}, {"s": 1, "en": "Well, I used to enjoy the night shifts, but now I'd like a schedule that lets me study in the evenings.", "pt": "Bom, eu gostava dos turnos da noite, mas agora queria um horário que me deixe estudar à noite."}, {"s": 0, "en": "That makes sense. What would you do if a customer got really angry on the phone?", "pt": "Faz sentido. O que você faria se um cliente ficasse muito irritado no telefone?"}, {"s": 1, "en": "I'd stay calm, listen first, and try to find a solution. If I couldn't solve it, I'd ask a supervisor.", "pt": "Eu manteria a calma, ouviria primeiro e tentaria achar uma solução. Se não conseguisse resolver, chamaria um supervisor."}, {"s": 0, "en": "Good answer. Have you ever used any software for tracking customer tickets?", "pt": "Boa resposta. Você já usou algum software para acompanhar chamados de clientes?"}, {"s": 1, "en": "Actually, yes. We switched to a new system last year, and I helped train my coworkers on it.", "pt": "Na verdade, sim. Mudamos para um sistema novo no ano passado e eu ajudei a treinar meus colegas."}, {"s": 0, "en": "Perfect. We'll make a decision by Friday, and I'll give you a call either way.", "pt": "Perfeito. Vamos decidir até sexta e eu te ligo de qualquer jeito."}, {"s": 1, "en": "Thanks so much. I'm really looking forward to hearing from you.", "pt": "Muito obrigado. Fico no aguardo do seu retorno."}], "questions": [{"q": "Por que Daniel quer sair do emprego no hotel?", "options": ["Porque o salário é baixo", "Porque quer estudar à noite", "Porque não gosta dos colegas"], "answer": 1}, {"q": "O que Daniel fez quando o hotel mudou de sistema?", "options": ["Ajudou a treinar os colegas", "Reclamou com o gerente", "Pediu para mudar de setor"], "answer": 0}, {"q": "Quando a empresa vai tomar uma decisão?", "options": ["Na segunda-feira", "Hoje à noite", "Até sexta-feira"], "answer": 2}]}, {"id": "dB1-2", "level": "B1", "title": "A Faulty Coffee Maker", "titlePt": "Uma cafeteira com defeito", "setting": "Uma cliente volta a uma loja de eletrodomésticos para devolver uma cafeteira que parou de funcionar.", "speakers": [{"name": "Rachel", "g": "f"}, {"name": "Kevin", "g": "m"}], "lines": [{"s": 1, "en": "Hi there. How can I help you today?", "pt": "Olá. Como posso ajudar hoje?"}, {"s": 0, "en": "Hi. I bought this coffee maker here two weeks ago, and it's already stopped working.", "pt": "Oi. Comprei esta cafeteira aqui há duas semanas e ela já parou de funcionar."}, {"s": 1, "en": "Oh, I'm sorry about that. What exactly is the problem?", "pt": "Ah, sinto muito. Qual é exatamente o problema?"}, {"s": 0, "en": "It turns on, but the water doesn't heat up. I've tried cleaning it, but nothing has changed.", "pt": "Ela liga, mas a água não esquenta. Já tentei limpar, mas nada mudou."}, {"s": 1, "en": "Do you have the receipt with you?", "pt": "A senhora está com o recibo?"}, {"s": 0, "en": "Yes, here it is. I'd really like my money back, if possible.", "pt": "Sim, aqui está. Eu queria muito o meu dinheiro de volta, se possível."}, {"s": 1, "en": "Well, since it's less than thirty days, you can get a refund or swap it for a new one.", "pt": "Bom, como faz menos de trinta dias, a senhora pode receber o reembolso ou trocar por uma nova."}, {"s": 0, "en": "Hmm, if you had a different model, I might take that instead.", "pt": "Hum, se vocês tivessem outro modelo, talvez eu levasse esse."}, {"s": 1, "en": "We've got a slightly bigger one for ten dollars more. It's been really popular.", "pt": "Temos uma um pouco maior por dez dólares a mais. Ela tem vendido muito."}, {"s": 0, "en": "Okay, I'll go with that one, then. I'll pay the difference.", "pt": "Tá bom, vou ficar com essa, então. Eu pago a diferença."}], "questions": [{"q": "Qual era o problema da cafeteira?", "options": ["Não ligava", "Vazava água", "A água não esquentava"], "answer": 2}, {"q": "No início, o que Rachel queria?", "options": ["O dinheiro de volta", "Um desconto", "Um conserto gratuito"], "answer": 0}, {"q": "O que Rachel decide no final?", "options": ["Pegar o reembolso", "Levar um modelo maior e pagar a diferença", "Voltar outro dia"], "answer": 1}]}, {"id": "dB1-3", "level": "B1", "title": "Planning a Beach Trip", "titlePt": "Planejando uma viagem à praia", "setting": "Dois amigos planejam um fim de semana prolongado na praia e discutem transporte e hospedagem.", "speakers": [{"name": "Sophie", "g": "f"}, {"name": "Mark", "g": "m"}], "lines": [{"s": 0, "en": "So, are we still going to the coast for the long weekend?", "pt": "E aí, ainda vamos para o litoral no feriado prolongado?"}, {"s": 1, "en": "Definitely. I've already asked for Friday off. Should we drive or take the bus?", "pt": "Com certeza. Já pedi folga na sexta. A gente vai de carro ou de ônibus?"}, {"s": 0, "en": "If we drive, we'll have to deal with traffic. The bus might be more relaxing.", "pt": "Se formos de carro, vamos ter que enfrentar trânsito. O ônibus pode ser mais tranquilo."}, {"s": 1, "en": "True, but the bus only leaves at six in the morning. I'm not a morning person.", "pt": "Verdade, mas o ônibus só sai às seis da manhã. Eu não sou uma pessoa matinal."}, {"s": 0, "en": "Come on, you can sleep on the bus! And we won't have to pay for gas or parking.", "pt": "Ah, vai, você pode dormir no ônibus! E não vamos ter que pagar gasolina nem estacionamento."}, {"s": 1, "en": "Fair enough. What about a place to stay? Hotels near the beach are pretty expensive.", "pt": "Justo. E onde a gente fica? Os hotéis perto da praia são bem caros."}, {"s": 0, "en": "My cousin rents out a small apartment there. If it's free, she'll give us a good price.", "pt": "Minha prima aluga um apartamentinho lá. Se estiver livre, ela faz um preço bom pra gente."}, {"s": 1, "en": "That would be awesome. Can you check with her tonight?", "pt": "Isso seria ótimo. Você pode confirmar com ela hoje à noite?"}, {"s": 0, "en": "Sure. And you should book the bus tickets before they sell out.", "pt": "Claro. E você devia reservar as passagens de ônibus antes que esgotem."}], "questions": [{"q": "Por que Mark hesita em ir de ônibus?", "options": ["Porque é caro", "Porque o ônibus sai muito cedo", "Porque fica enjoado"], "answer": 1}, {"q": "Qual vantagem do ônibus Sophie menciona?", "options": ["Não pagar gasolina nem estacionamento", "Chegar mais rápido", "Ter Wi-Fi a bordo"], "answer": 0}, {"q": "Qual é a tarefa de Mark?", "options": ["Falar com a prima", "Alugar um carro", "Reservar as passagens de ônibus"], "answer": 2}]}, {"id": "dB1-4", "level": "B1", "title": "The Broken Heater", "titlePt": "O aquecedor quebrado", "setting": "Uma inquilina liga para o proprietário porque o aquecedor do apartamento não está funcionando.", "speakers": [{"name": "Nina", "g": "f"}, {"name": "Greg", "g": "m"}], "lines": [{"s": 0, "en": "Hi, Greg, it's Nina from apartment 3B. I'm sorry to bother you, but the heater's broken again.", "pt": "Oi, Greg, é a Nina do apartamento 3B. Desculpa incomodar, mas o aquecedor quebrou de novo."}, {"s": 1, "en": "Again? Didn't the repairman fix it last month?", "pt": "De novo? O técnico não consertou no mês passado?"}, {"s": 0, "en": "He did, but it only worked for about two weeks. It's been freezing in here since Sunday.", "pt": "Consertou, mas só funcionou umas duas semanas. Está congelando aqui desde domingo."}, {"s": 1, "en": "I'm sorry to hear that. I'll call him this afternoon and see when he can come over.", "pt": "Sinto muito. Vou ligar para ele hoje à tarde e ver quando ele pode passar aí."}, {"s": 0, "en": "Thanks. Honestly, I think it might be time to replace the whole thing. It's really old.", "pt": "Obrigada. Sinceramente, acho que talvez seja hora de trocar o aparelho inteiro. Ele é muito velho."}, {"s": 1, "en": "You might be right. If he says it can't be fixed properly, I'll buy a new one.", "pt": "Talvez você tenha razão. Se ele disser que não dá para consertar direito, eu compro um novo."}, {"s": 0, "en": "That would be great. In the meantime, could I use a space heater? Would that be okay?", "pt": "Seria ótimo. Enquanto isso, posso usar um aquecedor portátil? Tudo bem?"}, {"s": 1, "en": "Sure, just don't leave it on when you go out. I don't want any accidents.", "pt": "Claro, só não deixe ligado quando sair. Não quero nenhum acidente."}, {"s": 0, "en": "Of course. Just let me know when the repairman's coming so I can be home.", "pt": "Claro. Só me avisa quando o técnico vier, para eu estar em casa."}], "questions": [{"q": "Há quanto tempo o aquecedor está sem funcionar?", "options": ["Desde domingo", "Há um mês", "Desde ontem à noite"], "answer": 0}, {"q": "Em que situação Greg vai comprar um aquecedor novo?", "options": ["Se Nina pagar metade", "Se o técnico disser que não dá para consertar direito", "Se o inverno ficar mais frio"], "answer": 1}, {"q": "Qual condição Greg impõe para o uso do aquecedor portátil?", "options": ["Usar só à noite", "Pagar a conta de luz extra", "Não deixá-lo ligado ao sair"], "answer": 2}]}, {"id": "dB1-5", "level": "B1", "title": "Catching Up", "titlePt": "Colocando o papo em dia", "setting": "Dois antigos colegas de faculdade se encontram por acaso em um café depois de anos sem se ver.", "speakers": [{"name": "Julia", "g": "f"}, {"name": "Ben", "g": "m"}], "lines": [{"s": 1, "en": "Julia? No way! I haven't seen you since graduation!", "pt": "Julia? Não acredito! Não te vejo desde a formatura!"}, {"s": 0, "en": "Ben! Wow, it's been ages. What have you been up to?", "pt": "Ben! Nossa, quanto tempo. O que você tem feito?"}, {"s": 1, "en": "Well, I moved to Chicago for a while, but I came back last year. I'm teaching math now.", "pt": "Bom, me mudei para Chicago por um tempo, mas voltei no ano passado. Agora dou aula de matemática."}, {"s": 0, "en": "A teacher? You used to hate getting up early!", "pt": "Professor? Você odiava acordar cedo!"}, {"s": 1, "en": "I know, right? I still do, actually. But I really love the job. What about you?", "pt": "Pois é, né? Na verdade, ainda odeio. Mas amo o trabalho. E você?"}, {"s": 0, "en": "I've been working as a nurse for five years. And I got married two years ago.", "pt": "Trabalho como enfermeira há cinco anos. E me casei há dois anos."}, {"s": 1, "en": "Congratulations! Anyone I know?", "pt": "Parabéns! Alguém que eu conheça?"}, {"s": 0, "en": "Actually, yes. Remember Sam from our chemistry class? We ran into each other at a wedding.", "pt": "Na verdade, sim. Lembra do Sam da aula de química? A gente se reencontrou num casamento."}, {"s": 1, "en": "That's amazing! We should all get together for dinner sometime.", "pt": "Que incrível! A gente devia se juntar para jantar qualquer dia."}, {"s": 0, "en": "I'd love that. Give me your number and I'll text you this week.", "pt": "Eu adoraria. Me passa seu número que eu te mando mensagem esta semana."}], "questions": [{"q": "O que Ben faz atualmente?", "options": ["É enfermeiro", "Estuda química", "É professor de matemática"], "answer": 2}, {"q": "O que Julia acha surpreendente sobre a profissão de Ben?", "options": ["Ele odiava acordar cedo", "Ele não gostava de crianças", "Ele queria ser médico"], "answer": 0}, {"q": "Como Julia reencontrou o marido?", "options": ["Na aula de química", "Em um casamento", "Em Chicago"], "answer": 1}]}, {"id": "dB1-6", "level": "B1", "title": "Trouble Sleeping", "titlePt": "Dificuldade para dormir", "setting": "Um paciente vai a uma consulta médica porque tem dormido mal nas últimas semanas.", "speakers": [{"name": "Dr. Ramos", "g": "f"}, {"name": "Chris", "g": "m"}], "lines": [{"s": 0, "en": "Good morning, Chris. What brings you in today?", "pt": "Bom dia, Chris. O que te traz aqui hoje?"}, {"s": 1, "en": "I haven't been sleeping well for about three weeks. I wake up at three and can't fall back asleep.", "pt": "Não tenho dormido bem há umas três semanas. Acordo às três e não consigo voltar a dormir."}, {"s": 0, "en": "I see. Has anything changed in your routine lately?", "pt": "Entendi. Mudou alguma coisa na sua rotina ultimamente?"}, {"s": 1, "en": "Well, I started a new job, and I've been working late a lot. I'm usually on my laptop until midnight.", "pt": "Bom, comecei num emprego novo e tenho trabalhado até tarde. Normalmente fico no notebook até meia-noite."}, {"s": 0, "en": "And how much coffee do you drink a day?", "pt": "E quanto café você toma por dia?"}, {"s": 1, "en": "Maybe four or five cups. I need it to get through the afternoon.", "pt": "Talvez quatro ou cinco xícaras. Preciso dele para aguentar a tarde."}, {"s": 0, "en": "That could be part of the problem. I'd like you to stop drinking coffee after lunch.", "pt": "Isso pode ser parte do problema. Quero que você pare de tomar café depois do almoço."}, {"s": 1, "en": "Okay. Should I take any medication?", "pt": "Tá bom. Devo tomar algum remédio?"}, {"s": 0, "en": "Not yet. Try turning off screens an hour before bed. If nothing changes in two weeks, come back.", "pt": "Ainda não. Tente desligar as telas uma hora antes de dormir. Se nada mudar em duas semanas, volte."}, {"s": 1, "en": "Got it. I'll give it a try. Thanks, doctor.", "pt": "Entendi. Vou tentar. Obrigado, doutora."}], "questions": [{"q": "Segundo Chris, o que mudou na rotina dele?", "options": ["Ele começou a fazer academia", "Ele começou um emprego novo e trabalha até tarde", "Ele se mudou de casa"], "answer": 1}, {"q": "O que a médica recomenda sobre o café?", "options": ["Parar de tomar depois do almoço", "Tomar só de manhã cedo e à noite", "Parar completamente"], "answer": 0}, {"q": "O que Chris deve fazer se não melhorar?", "options": ["Tomar um remédio para dormir", "Mudar de emprego", "Voltar ao consultório em duas semanas"], "answer": 2}]}, {"id": "dB1-7", "level": "B1", "title": "Choosing a Course", "titlePt": "Escolhendo um curso", "setting": "Um adulto conversa com uma orientadora de uma escola técnica sobre qual curso noturno fazer.", "speakers": [{"name": "Megan", "g": "f"}, {"name": "Luis", "g": "m"}], "lines": [{"s": 1, "en": "Hi, I'm thinking about taking an evening course, but I can't decide between graphic design and web development.", "pt": "Oi, estou pensando em fazer um curso noturno, mas não consigo decidir entre design gráfico e desenvolvimento web."}, {"s": 0, "en": "Both are great options. What do you do now?", "pt": "As duas são ótimas opções. O que você faz atualmente?"}, {"s": 1, "en": "I work in a print shop. I used to draw a lot when I was younger, but I've never studied it.", "pt": "Trabalho numa gráfica. Eu desenhava muito quando era mais novo, mas nunca estudei isso."}, {"s": 0, "en": "Well, if you enjoy drawing, graphic design might feel more natural for you.", "pt": "Bom, se você gosta de desenhar, design gráfico pode ser mais natural para você."}, {"s": 1, "en": "Maybe, but I've heard web developers earn more money.", "pt": "Talvez, mas ouvi dizer que desenvolvedores web ganham mais."}, {"s": 0, "en": "That's often true. But the web course has a lot of coding, and it's two nights a week for a year.", "pt": "Geralmente é verdade. Mas o curso de web tem muita programação e são duas noites por semana durante um ano."}, {"s": 1, "en": "And the design course?", "pt": "E o curso de design?"}, {"s": 0, "en": "It's six months, three nights a week. You could always take web development later.", "pt": "São seis meses, três noites por semana. Você sempre pode fazer desenvolvimento web depois."}, {"s": 1, "en": "That sounds like a good plan. I think I'll sign up for design first.", "pt": "Parece um bom plano. Acho que vou me inscrever em design primeiro."}], "questions": [{"q": "Por que a orientadora sugere design gráfico?", "options": ["Porque é mais barato", "Porque Luis gostava de desenhar", "Porque é online"], "answer": 1}, {"q": "Quanto tempo dura o curso de desenvolvimento web?", "options": ["Seis meses", "Dois anos", "Um ano"], "answer": 2}, {"q": "O que Luis decide?", "options": ["Fazer design primeiro", "Fazer os dois cursos ao mesmo tempo", "Pensar mais e voltar depois"], "answer": 0}]}, {"id": "dB1-8", "level": "B1", "title": "Sharing the Chores", "titlePt": "Dividindo as tarefas", "setting": "Dois colegas de apartamento discutem como dividir as tarefas domésticas de forma mais justa.", "speakers": [{"name": "Hannah", "g": "f"}, {"name": "Jake", "g": "m"}], "lines": [{"s": 0, "en": "Jake, can we talk for a minute? I feel like I've been doing most of the cleaning lately.", "pt": "Jake, a gente pode conversar um minuto? Sinto que tenho feito a maior parte da limpeza ultimamente."}, {"s": 1, "en": "Oh, really? I'm sorry. I've been so busy with work that I haven't noticed.", "pt": "Ah, é mesmo? Desculpa. Ando tão ocupado com o trabalho que nem percebi."}, {"s": 0, "en": "I get it, but the dishes pile up every night, and I always end up washing them.", "pt": "Eu entendo, mas a louça acumula toda noite e eu sempre acabo lavando."}, {"s": 1, "en": "Fair point. What if we made a schedule and put it on the fridge?", "pt": "Tem razão. E se a gente fizesse uma escala e colocasse na geladeira?"}, {"s": 0, "en": "That could work. I don't mind cooking if you take care of the dishes.", "pt": "Pode funcionar. Eu não me importo de cozinhar se você cuidar da louça."}, {"s": 1, "en": "Deal. And I can take out the trash, too. What about the bathroom?", "pt": "Fechado. E eu posso levar o lixo também. E o banheiro?"}, {"s": 0, "en": "Let's take turns. I'll do it this week, and you can do it next week.", "pt": "Vamos revezar. Eu faço esta semana e você faz semana que vem."}, {"s": 1, "en": "Sounds fair. You should have told me sooner, you know.", "pt": "Parece justo. Você devia ter me falado antes, sabia?"}, {"s": 0, "en": "I know. I didn't want to start an argument. Thanks for being so understanding.", "pt": "Eu sei. Não queria começar uma briga. Obrigada por ser tão compreensivo."}], "questions": [{"q": "Qual era a principal reclamação de Hannah?", "options": ["Jake fazia muito barulho", "Jake não pagava as contas", "A louça acumulava e ela sempre lavava"], "answer": 2}, {"q": "Como eles vão dividir a limpeza do banheiro?", "options": ["Vão revezar a cada semana", "Jake vai limpar sempre", "Vão contratar uma faxineira"], "answer": 0}, {"q": "Qual é a atitude de Jake durante a conversa?", "options": ["Fica irritado e na defensiva", "É compreensivo e aceita mudar", "Ignora o problema"], "answer": 1}]}, {"id": "dB2-1", "level": "B2", "title": "Behind Schedule", "titlePt": "Atrasados no cronograma", "setting": "Dois colegas de trabalho discutem por que um projeto está atrasado e como explicar isso à diretoria.", "speakers": [{"name": "Karen", "g": "f"}, {"name": "Steve", "g": "m"}], "lines": [{"s": 0, "en": "Steve, got a sec? I just heard the client portal won't be ready by the fifteenth.", "pt": "Steve, tem um segundo? Acabei de saber que o portal do cliente não vai ficar pronto até o dia quinze."}, {"s": 1, "en": "Yeah, I was going to bring it up at the meeting. We're about two weeks behind.", "pt": "É, eu ia comentar na reunião. Estamos umas duas semanas atrasados."}, {"s": 0, "en": "Two weeks? What happened? Last time we talked, you said things were on track.", "pt": "Duas semanas? O que aconteceu? Da última vez que conversamos, você disse que estava tudo em dia."}, {"s": 1, "en": "They were, until the design team was asked to redo the whole login page.", "pt": "Estava, até pedirem para a equipe de design refazer a página de login inteira."}, {"s": 0, "en": "Who asked for that? It wasn't in the original scope.", "pt": "Quem pediu isso? Não estava no escopo original."}, {"s": 1, "en": "Apparently, the client's legal department insisted on it. Something about data privacy rules.", "pt": "Pelo visto, o jurídico do cliente insistiu. Algo sobre regras de privacidade de dados."}, {"s": 0, "en": "Well, that's not really on us, then. Has anyone told management?", "pt": "Bom, então isso não é bem culpa nossa. Alguém avisou a diretoria?"}, {"s": 1, "en": "Not officially. I mean, I mentioned it to Linda, but I don't think it really sank in.", "pt": "Não oficialmente. Quer dizer, comentei com a Linda, mas acho que ela não absorveu muito bem."}, {"s": 0, "en": "We'd better put it in writing. If it's documented, nobody can point fingers at us later.", "pt": "É melhor a gente colocar por escrito. Se estiver documentado, ninguém pode jogar a culpa na gente depois."}, {"s": 1, "en": "Good call. I'll draft an email tonight explaining the change request and the new timeline.", "pt": "Boa ideia. Vou escrever um e-mail hoje à noite explicando o pedido de mudança e o novo prazo."}, {"s": 0, "en": "Send it to me first. I'd like to tone it down a bit so it doesn't sound like we're complaining.", "pt": "Manda para mim primeiro. Quero suavizar um pouco para não parecer que estamos reclamando."}], "questions": [{"q": "Qual foi a causa do atraso?", "options": ["Um funcionário pediu demissão", "A página de login teve que ser refeita a pedido do cliente", "O servidor caiu por vários dias"], "answer": 1}, {"q": "Por que Karen quer colocar tudo por escrito?", "options": ["Para evitar que culpem a equipe depois", "Para pedir aumento", "Para cancelar o projeto"], "answer": 0}, {"q": "O que Karen pretende fazer com o e-mail de Steve?", "options": ["Enviar direto ao cliente", "Traduzir para o jurídico", "Suavizar o tom antes do envio"], "answer": 2}]}, {"id": "dB2-2", "level": "B2", "title": "Negotiating a Deadline", "titlePt": "Negociando um prazo", "setting": "Uma cliente e um tradutor freelancer negociam um prazo mais curto para um trabalho urgente.", "speakers": [{"name": "Olivia", "g": "f"}, {"name": "Ryan", "g": "m"}], "lines": [{"s": 0, "en": "Ryan, I know we agreed on the twentieth, but is there any chance you could deliver by the twelfth?", "pt": "Ryan, sei que combinamos o dia vinte, mas existe alguma chance de você entregar até o dia doze?"}, {"s": 1, "en": "The twelfth? That's over a week earlier. Can I ask what's changed?", "pt": "Dia doze? Isso é mais de uma semana antes. Posso perguntar o que mudou?"}, {"s": 0, "en": "Our board meeting was moved up, and they want the translated report in hand before it.", "pt": "A reunião do conselho foi antecipada e eles querem o relatório traduzido em mãos antes dela."}, {"s": 1, "en": "I see. Honestly, it's doable, but I'd have to turn down another project to make it work.", "pt": "Entendi. Sinceramente, dá para fazer, mas eu teria que recusar outro projeto para isso."}, {"s": 0, "en": "I understand that's asking a lot. Would a rush fee make it worth your while?", "pt": "Entendo que é pedir muito. Uma taxa de urgência faria valer a pena para você?"}, {"s": 1, "en": "It would help. I usually charge an extra twenty-five percent for anything under a week.", "pt": "Ajudaria. Normalmente cobro vinte e cinco por cento a mais para qualquer coisa com menos de uma semana."}, {"s": 0, "en": "Hmm, that's a bit steep for us. Could we meet halfway, say fifteen percent?", "pt": "Hum, é meio salgado para nós. Podemos chegar a um meio-termo, tipo quinze por cento?"}, {"s": 1, "en": "How about this: fifteen percent, but you send me the final charts by tomorrow morning.", "pt": "Que tal assim: quinze por cento, mas você me manda os gráficos finais até amanhã de manhã."}, {"s": 0, "en": "I think that's fair. I'll have to double-check with finance, but I'm pretty sure they'll sign off on it.", "pt": "Acho justo. Vou ter que confirmar com o financeiro, mas tenho quase certeza de que eles vão aprovar."}, {"s": 1, "en": "Great. Once you confirm, I'll block off my schedule and get started right away.", "pt": "Ótimo. Assim que você confirmar, eu reservo minha agenda e começo na hora."}], "questions": [{"q": "Por que Olivia precisa do trabalho mais cedo?", "options": ["Ela vai sair de férias", "O cliente dela cancelou o contrato", "A reunião do conselho foi antecipada"], "answer": 2}, {"q": "Qual taxa de urgência eles combinam?", "options": ["Quinze por cento", "Vinte e cinco por cento", "Vinte por cento"], "answer": 0}, {"q": "Qual condição Ryan impõe?", "options": ["Receber o pagamento adiantado", "Receber os gráficos finais até a manhã seguinte", "Trabalhar só nos dias úteis"], "answer": 1}]}, {"id": "dB2-3", "level": "B2", "title": "Noise Upstairs", "titlePt": "Barulho no andar de cima", "setting": "Uma moradora vai até o apartamento de cima para reclamar, com educação, do barulho à noite.", "speakers": [{"name": "Diane", "g": "f"}, {"name": "Paul", "g": "m"}], "lines": [{"s": 0, "en": "Hi, sorry to bother you. I'm Diane, from downstairs. Do you have a minute?", "pt": "Oi, desculpe incomodar. Sou a Diane, do andar de baixo. Você tem um minuto?"}, {"s": 1, "en": "Sure. Is everything okay?", "pt": "Claro. Está tudo bem?"}, {"s": 0, "en": "Well, I don't want to make a big deal out of it, but there's been a lot of noise late at night.", "pt": "Bom, não quero fazer tempestade em copo d'água, mas tem tido muito barulho tarde da noite."}, {"s": 1, "en": "Oh no. Really? I had no idea it carried that much. What kind of noise?", "pt": "Ah, não. Sério? Não fazia ideia de que o som passava tanto. Que tipo de barulho?"}, {"s": 0, "en": "Mostly footsteps and something that sounds like furniture being moved, usually around one in the morning.", "pt": "Principalmente passos e algo que parece móveis sendo arrastados, geralmente por volta de uma da manhã."}, {"s": 1, "en": "Ah, that's probably me. I work the late shift at the hospital, so I get home pretty late.", "pt": "Ah, provavelmente sou eu. Trabalho no turno da noite no hospital, então chego bem tarde."}, {"s": 0, "en": "That explains it. I'm sure you're not doing it on purpose, but I have to be up at six.", "pt": "Isso explica. Tenho certeza de que você não faz de propósito, mas eu tenho que acordar às seis."}, {"s": 1, "en": "That's totally fair. I tend to move my chairs around when I'm cleaning up. I'll stop doing that.", "pt": "Faz todo sentido. Costumo arrastar as cadeiras quando estou arrumando. Vou parar de fazer isso."}, {"s": 0, "en": "Thanks. Maybe some rugs or felt pads under the chairs would help, too?", "pt": "Obrigada. Talvez uns tapetes ou feltros embaixo das cadeiras também ajudem?"}, {"s": 1, "en": "Good idea. I'll pick some up this weekend. And please, just knock if it happens again.", "pt": "Boa ideia. Vou comprar no fim de semana. E, por favor, é só bater na porta se acontecer de novo."}, {"s": 0, "en": "I will. I really appreciate how you've taken this. Some people get pretty defensive.", "pt": "Pode deixar. Agradeço muito a forma como você recebeu isso. Algumas pessoas ficam bem na defensiva."}], "questions": [{"q": "Por que Paul chega tarde em casa?", "options": ["Ele sai com amigos", "Ele trabalha no turno da noite no hospital", "Ele estuda à noite"], "answer": 1}, {"q": "O que provavelmente causava o barulho de móveis?", "options": ["Paul arrastando as cadeiras ao arrumar", "Uma reforma no apartamento", "O cachorro de Paul"], "answer": 0}, {"q": "Como Diane avalia a reação de Paul?", "options": ["Acha que ele foi grosseiro", "Acha que ele não levou a sério", "Fica grata porque ele não ficou na defensiva"], "answer": 2}]}, {"id": "dB2-4", "level": "B2", "title": "The Four-Day Week", "titlePt": "A semana de quatro dias", "setting": "Dois amigos comentam uma notícia sobre empresas que estão testando a semana de trabalho de quatro dias.", "speakers": [{"name": "Grace", "g": "f"}, {"name": "Ethan", "g": "m"}], "lines": [{"s": 1, "en": "Did you see that article about companies trying out a four-day work week?", "pt": "Você viu aquela matéria sobre empresas testando a semana de trabalho de quatro dias?"}, {"s": 0, "en": "I did! Apparently, productivity didn't drop at all. In some cases, it actually went up.", "pt": "Vi! Pelo visto, a produtividade não caiu nada. Em alguns casos, até aumentou."}, {"s": 1, "en": "That's what they claim, but I'm a bit skeptical. The study was only carried out for six months.", "pt": "É o que eles dizem, mas estou meio cético. O estudo foi feito só durante seis meses."}, {"s": 0, "en": "Fair enough, but most of the companies decided to keep the new schedule afterwards.", "pt": "Justo, mas a maioria das empresas decidiu manter o novo horário depois."}, {"s": 1, "en": "Sure, but those were mostly office jobs. It'd be a whole different ball game for hospitals or restaurants.", "pt": "Tá, mas eram em sua maioria trabalhos de escritório. Seria outra história para hospitais ou restaurantes."}, {"s": 0, "en": "I suppose so. Still, the article said employees reported feeling far less burned out.", "pt": "Acho que sim. Mesmo assim, a matéria disse que os funcionários relataram estar bem menos esgotados."}, {"s": 1, "en": "Well, who wouldn't? A three-day weekend every week sounds like a dream.", "pt": "Bom, quem não estaria? Um fim de semana de três dias toda semana parece um sonho."}, {"s": 0, "en": "Would you take it if your company offered it, even if your days got longer?", "pt": "Você aceitaria se a sua empresa oferecesse, mesmo que seus dias ficassem mais longos?"}, {"s": 1, "en": "In a heartbeat. I'd rather work ten hours a day and have Fridays off.", "pt": "Na hora. Prefiro trabalhar dez horas por dia e ter as sextas livres."}, {"s": 0, "en": "See? For someone who's so skeptical, you seem pretty convinced.", "pt": "Viu? Para alguém tão cético, você parece bem convencido."}, {"s": 1, "en": "Okay, okay. I just think it's too early to say it'll work everywhere.", "pt": "Tá bom, tá bom. Só acho que é cedo demais para dizer que vai funcionar em todo lugar."}], "questions": [{"q": "Por que Ethan está cético em relação ao estudo?", "options": ["Porque foi feito por uma única empresa", "Porque durou só seis meses e envolveu principalmente escritórios", "Porque a produtividade caiu"], "answer": 1}, {"q": "O que, segundo a matéria, os funcionários relataram?", "options": ["Que estavam menos esgotados", "Que ganhavam menos", "Que preferiam o horário antigo"], "answer": 0}, {"q": "Qual é a posição final de Ethan?", "options": ["Acha a ideia ruim para todos", "Não aceitaria a proposta", "Aceitaria para si, mas acha cedo para generalizar"], "answer": 2}]}, {"id": "dB2-5", "level": "B2", "title": "Booking a Venue", "titlePt": "Reservando um espaço", "setting": "Um homem conversa com a coordenadora de um salão de eventos para reservar o espaço para a festa de 40 anos da esposa.", "speakers": [{"name": "Melissa", "g": "f"}, {"name": "Tony", "g": "m"}], "lines": [{"s": 1, "en": "Hi, I'm calling about renting your rooftop space for a surprise party in March.", "pt": "Oi, estou ligando sobre alugar o terraço de vocês para uma festa surpresa em março."}, {"s": 0, "en": "Wonderful. Do you have a date in mind, and roughly how many guests are we talking about?", "pt": "Maravilha. Você já tem uma data em mente e mais ou menos quantos convidados seriam?"}, {"s": 1, "en": "Saturday the eighteenth, and around sixty people. It's my wife's fortieth birthday.", "pt": "Sábado, dia dezoito, e umas sessenta pessoas. É o aniversário de quarenta anos da minha esposa."}, {"s": 0, "en": "Let me check. Hmm, the rooftop's already been booked that evening, I'm afraid.", "pt": "Deixa eu ver. Hum, infelizmente o terraço já está reservado nessa noite."}, {"s": 1, "en": "Oh, that's a shame. Is there any other room available?", "pt": "Ah, que pena. Tem algum outro salão disponível?"}, {"s": 0, "en": "Our garden room is free. It's a bit smaller, but it can hold up to seventy, and it has a heated patio.", "pt": "Nosso salão do jardim está livre. É um pouco menor, mas cabe até setenta pessoas e tem um pátio aquecido."}, {"s": 1, "en": "That could work. What's included in the price?", "pt": "Pode dar certo. O que está incluído no preço?"}, {"s": 0, "en": "Tables, chairs and basic lighting. Catering and decorations are arranged separately, though we can recommend some vendors.", "pt": "Mesas, cadeiras e iluminação básica. Bufê e decoração são contratados à parte, mas podemos indicar alguns fornecedores."}, {"s": 1, "en": "And how much would you need as a deposit to hold the date?", "pt": "E quanto vocês precisariam de sinal para garantir a data?"}, {"s": 0, "en": "Thirty percent, which is non-refundable if you cancel less than a month before.", "pt": "Trinta por cento, que não é reembolsável se você cancelar com menos de um mês de antecedência."}, {"s": 1, "en": "Got it. I'd like to see the room before I commit. Could I swing by on Thursday?", "pt": "Entendi. Gostaria de ver o salão antes de fechar. Posso dar uma passada na quinta?"}, {"s": 0, "en": "Absolutely. I'll pencil you in for six o'clock, and I'll make sure your wife doesn't hear a word from us.", "pt": "Com certeza. Vou te agendar provisoriamente para as seis e garanto que sua esposa não vai saber de nada por nós."}], "questions": [{"q": "Por que Tony não pode alugar o terraço?", "options": ["Já está reservado nessa noite", "É pequeno demais para 60 pessoas", "Está em reforma"], "answer": 0}, {"q": "Qual é a regra sobre o sinal de 30%?", "options": ["É devolvido sempre", "Não é devolvido se cancelar com menos de um mês", "É descontado do bufê"], "answer": 1}, {"q": "O que Tony decide fazer antes de fechar?", "options": ["Contratar o bufê", "Consultar a esposa", "Visitar o salão na quinta"], "answer": 2}]}, {"id": "dB2-6", "level": "B2", "title": "Stuck on the Highway", "titlePt": "Parada na estrada", "setting": "Uma motorista liga para o serviço de assistência rodoviária depois que o carro dela para de funcionar.", "speakers": [{"name": "Amy", "g": "f"}, {"name": "Victor", "g": "m"}], "lines": [{"s": 1, "en": "Roadside assistance, this is Victor. How can I help?", "pt": "Assistência rodoviária, aqui é o Victor. Como posso ajudar?"}, {"s": 0, "en": "Hi, my car just broke down on the highway. It started making a weird noise and then it just died.", "pt": "Oi, meu carro acabou de quebrar na rodovia. Começou a fazer um barulho estranho e simplesmente morreu."}, {"s": 1, "en": "Okay, first things first. Are you somewhere safe, off the road?", "pt": "Certo, primeiro o mais importante. Você está num lugar seguro, fora da pista?"}, {"s": 0, "en": "I managed to pull over onto the shoulder, and my hazard lights are on.", "pt": "Consegui encostar no acostamento e o pisca-alerta está ligado."}, {"s": 1, "en": "Good. Can you tell me where you are? Any exit numbers or signs nearby?", "pt": "Ótimo. Pode me dizer onde você está? Algum número de saída ou placa por perto?"}, {"s": 0, "en": "I just passed exit 42, heading north. There's a gas station sign up ahead.", "pt": "Acabei de passar a saída 42, sentido norte. Tem uma placa de posto de gasolina mais à frente."}, {"s": 1, "en": "Got it. Did you notice any warning lights on the dashboard before it stopped?", "pt": "Certo. Você notou alguma luz de alerta no painel antes de parar?"}, {"s": 0, "en": "Now that you mention it, the temperature light came on a few minutes earlier. I guess I should've stopped then.", "pt": "Agora que você falou, a luz de temperatura acendeu alguns minutos antes. Acho que eu devia ter parado naquela hora."}, {"s": 1, "en": "Sounds like it may have overheated. Don't try to open the hood yet; it could still be really hot.", "pt": "Parece que pode ter superaquecido. Não tente abrir o capô ainda; ainda pode estar muito quente."}, {"s": 0, "en": "Okay. How long will it take for someone to get here?", "pt": "Tá. Quanto tempo vai levar para alguém chegar aqui?"}, {"s": 1, "en": "A tow truck's been dispatched. It should be there in about forty minutes. Stay inside the car with your seatbelt on.", "pt": "Um guincho já foi enviado. Deve chegar em uns quarenta minutos. Fique dentro do carro com o cinto de segurança."}], "questions": [{"q": "O que Amy percebeu antes de o carro parar?", "options": ["A luz do óleo acendeu", "Um pneu furou", "A luz de temperatura acendeu"], "answer": 2}, {"q": "Por que Victor diz para Amy não abrir o capô?", "options": ["Porque o motor ainda pode estar muito quente", "Porque é proibido na rodovia", "Porque o guincho já está chegando"], "answer": 0}, {"q": "Em quanto tempo o guincho deve chegar?", "options": ["Vinte minutos", "Cerca de quarenta minutos", "Uma hora"], "answer": 1}]}, {"id": "dB2-7", "level": "B2", "title": "Feedback on a Presentation", "titlePt": "Feedback sobre uma apresentação", "setting": "Uma gerente dá feedback a um funcionário sobre a apresentação que ele fez para clientes.", "speakers": [{"name": "Claire", "g": "f"}, {"name": "Josh", "g": "m"}], "lines": [{"s": 0, "en": "Josh, do you have a few minutes? I wanted to give you some feedback on yesterday's presentation.", "pt": "Josh, você tem uns minutos? Queria te dar um feedback sobre a apresentação de ontem."}, {"s": 1, "en": "Sure. Honestly, I felt like it went okay, but I was pretty nervous.", "pt": "Claro. Sinceramente, achei que foi ok, mas eu estava bem nervoso."}, {"s": 0, "en": "It didn't show much. Your research was really solid, and the client said the data was very convincing.", "pt": "Não deu para perceber muito. Sua pesquisa estava muito sólida, e o cliente disse que os dados foram bem convincentes."}, {"s": 1, "en": "That's a relief. Was there anything you think I could've done better?", "pt": "Que alívio. Teve alguma coisa que você acha que eu poderia ter feito melhor?"}, {"s": 0, "en": "Well, if I'm being honest, it ran a bit long. You were supposed to take twenty minutes, and it took almost forty.", "pt": "Bom, para ser sincera, ficou um pouco longa. Você deveria usar vinte minutos e levou quase quarenta."}, {"s": 1, "en": "Oh, wow. I didn't realize it was that long. I guess I got carried away with the details.", "pt": "Nossa. Não percebi que tinha sido tanto. Acho que me empolguei com os detalhes."}, {"s": 0, "en": "It happens. A few people seemed to tune out toward the end, which is a shame because your recommendations came last.", "pt": "Acontece. Algumas pessoas pareceram se desligar no final, o que é uma pena, porque suas recomendações vieram por último."}, {"s": 1, "en": "That makes sense. Maybe I should start with the recommendations and then back them up with the data.", "pt": "Faz sentido. Talvez eu deva começar com as recomendações e depois sustentá-las com os dados."}, {"s": 0, "en": "Exactly. Lead with the big picture. And it might be worth doing a timed rehearsal with someone beforehand.", "pt": "Exatamente. Comece pelo panorama geral. E talvez valha a pena fazer um ensaio cronometrado com alguém antes."}, {"s": 1, "en": "Would you mind sitting in on a run-through before the next one?", "pt": "Você se importaria de assistir a um ensaio antes da próxima?"}, {"s": 0, "en": "Not at all. Just book thirty minutes in my calendar next week.", "pt": "De jeito nenhum. É só marcar trinta minutos na minha agenda semana que vem."}], "questions": [{"q": "Qual foi o principal ponto negativo da apresentação?", "options": ["Os dados estavam errados", "Durou quase o dobro do tempo previsto", "Josh esqueceu os slides"], "answer": 1}, {"q": "Por que foi ruim algumas pessoas se desligarem no final?", "options": ["Porque as recomendações vieram por último", "Porque o cliente fez perguntas", "Porque havia um vídeo importante"], "answer": 0}, {"q": "O que Josh pede a Claire?", "options": ["Que ela faça a próxima apresentação", "Mais tempo para a pesquisa", "Que ela assista a um ensaio antes da próxima"], "answer": 2}]}, {"id": "dB2-8", "level": "B2", "title": "Missed Connection", "titlePt": "Conexão perdida", "setting": "Um passageiro perde o voo de conexão por causa de um atraso e conversa com uma atendente no balcão do aeroporto.", "speakers": [{"name": "Natalie", "g": "f"}, {"name": "Marcus", "g": "m"}], "lines": [{"s": 1, "en": "Hi. My flight from Denver was delayed, and I've missed my connection to Boston. What are my options?", "pt": "Oi. Meu voo de Denver atrasou e eu perdi a conexão para Boston. Quais são as minhas opções?"}, {"s": 0, "en": "I'm sorry to hear that. Let me pull up your booking. Okay, I can see the delay was caused by weather.", "pt": "Sinto muito. Deixa eu abrir sua reserva. Certo, vejo que o atraso foi causado pelo tempo."}, {"s": 1, "en": "Does that make a difference?", "pt": "Isso faz diferença?"}, {"s": 0, "en": "It does, unfortunately. Since it's weather-related, we're not required to cover a hotel, but I'll rebook you at no charge.", "pt": "Faz, infelizmente. Como foi por causa do tempo, não somos obrigados a cobrir hotel, mas vou remarcar você sem custo."}, {"s": 1, "en": "Okay. When's the next flight out?", "pt": "Tá. Quando sai o próximo voo?"}, {"s": 0, "en": "The next available seat is tomorrow at 7:15 a.m. Tonight's last flight is fully booked, I'm afraid.", "pt": "O próximo assento disponível é amanhã às 7h15. O último voo de hoje está lotado, infelizmente."}, {"s": 1, "en": "Tomorrow morning? I've got a meeting at ten. Is there any way I could be put on a waiting list for tonight?", "pt": "Amanhã de manhã? Tenho uma reunião às dez. Tem algum jeito de me colocarem numa lista de espera para hoje?"}, {"s": 0, "en": "Sure, I can add you, but to be honest, you're fifth on the list, so I wouldn't count on it.", "pt": "Claro, posso te incluir, mas, para ser sincera, você é o quinto da lista, então eu não contaria com isso."}, {"s": 1, "en": "Fair enough. Go ahead and confirm the morning flight, and put me on the waiting list just in case.", "pt": "Justo. Pode confirmar o voo da manhã e me colocar na lista de espera, só por garantia."}, {"s": 0, "en": "Done. And here's a voucher for a discounted rate at the airport hotel. It's not much, but it should help.", "pt": "Pronto. E aqui está um voucher com desconto no hotel do aeroporto. Não é muito, mas deve ajudar."}, {"s": 1, "en": "I appreciate that. I know none of this is your fault.", "pt": "Agradeço. Sei que nada disso é culpa sua."}], "questions": [{"q": "Por que a companhia aérea não é obrigada a pagar o hotel?", "options": ["Porque Marcus comprou a passagem mais barata", "Porque o atraso foi causado pelo tempo", "Porque o hotel está lotado"], "answer": 1}, {"q": "Por que a atendente diz para Marcus não contar com a lista de espera?", "options": ["Porque ele é o quinto da lista", "Porque o voo foi cancelado", "Porque a lista já fechou"], "answer": 0}, {"q": "Qual é a atitude de Marcus no final?", "options": ["Exige falar com o gerente", "Ameaça processar a companhia", "Agradece e reconhece que a culpa não é dela"], "answer": 2}]}, {"id": "dC1-1", "level": "C1", "title": "Back to the Office?", "titlePt": "De volta ao escritório?", "setting": "Dois gerentes discutem uma nova proposta da empresa que exige o retorno ao trabalho presencial.", "speakers": [{"name": "Rachel", "g": "f"}, {"name": "Marcus", "g": "m"}], "lines": [{"s": 0, "en": "So, have you had a chance to look over the new return-to-office proposal, or are you still pretending it doesn't exist?", "pt": "E aí, você já teve a chance de dar uma olhada na nova proposta de volta ao escritório, ou ainda está fingindo que ela não existe?"}, {"s": 1, "en": "I've read it. Twice, actually. And honestly, I think it's a step in the right direction, even if the rollout is a bit clumsy.", "pt": "Eu li. Duas vezes, na verdade. E, sinceramente, acho que é um passo na direção certa, mesmo que a implementação esteja meio desajeitada."}, {"s": 0, "en": "A step in the right direction? Marcus, my team's productivity went up when we went remote. The numbers back that up.", "pt": "Um passo na direção certa? Marcus, a produtividade da minha equipe aumentou quando passamos para o remoto. Os números comprovam isso."}, {"s": 1, "en": "Sure, output went up. But I'm talking about the stuff you can't measure, like mentoring junior people or solving a problem over coffee.", "pt": "Claro, a produção aumentou. Mas estou falando das coisas que não dá pra medir, tipo orientar o pessoal júnior ou resolver um problema tomando um café."}, {"s": 0, "en": "I get that, I really do. But forcing everyone back four days a week feels like using a sledgehammer to crack a nut.", "pt": "Eu entendo, de verdade. Mas obrigar todo mundo a voltar quatro dias por semana parece usar uma marreta pra quebrar uma noz."}, {"s": 1, "en": "Fair point. Four days might be overkill. What if we pushed for three, with each team choosing which days?", "pt": "Bom argumento. Quatro dias talvez seja exagero. E se a gente defendesse três, com cada equipe escolhendo quais dias?"}, {"s": 0, "en": "That's more like it. Although I'd want some flexibility for people with long commutes or kids at home.", "pt": "Assim fica melhor. Se bem que eu ia querer alguma flexibilidade para quem mora longe ou tem filhos em casa."}, {"s": 1, "en": "Absolutely. Look, I'm not trying to chain anyone to their desk. I just think we've lost something as a team.", "pt": "Com certeza. Olha, não estou tentando acorrentar ninguém à mesa. Só acho que perdemos alguma coisa como equipe."}, {"s": 0, "en": "Okay, I'll admit the new hires seem a little lost. Half of them have never even met their manager in person.", "pt": "Tá, admito que os novatos parecem meio perdidos. Metade deles nunca nem conheceu o gestor pessoalmente."}, {"s": 1, "en": "Exactly. So why don't we put together a counterproposal before Friday's meeting? We'd carry more weight together.", "pt": "Exatamente. Então por que a gente não monta uma contraproposta antes da reunião de sexta? Juntos a gente teria mais peso."}, {"s": 0, "en": "Deal. But if they come back with five days, I'm blaming you.", "pt": "Fechado. Mas se eles voltarem com cinco dias, a culpa é sua."}], "questions": [{"q": "Qual é a posição inicial de Rachel sobre a proposta?", "options": ["Ela acha a proposta exagerada e desnecessária", "Ela concorda totalmente com a volta ao escritório", "Ela ainda não leu a proposta"], "answer": 0}, {"q": "O que Marcus valoriza no trabalho presencial?", "options": ["O aumento da produtividade mensurável", "O controle sobre os horários dos funcionários", "A orientação de juniores e a colaboração espontânea"], "answer": 2}, {"q": "Como a conversa termina?", "options": ["Rachel desiste e aceita os quatro dias", "Eles decidem preparar juntos uma contraproposta", "Marcus passa a apoiar o trabalho totalmente remoto"], "answer": 1}]}, {"id": "dC1-2", "level": "C1", "title": "Negotiating the Offer", "titlePt": "Negociando a proposta", "setting": "Uma candidata negocia o salário de uma vaga com o responsável pelo RH da empresa.", "speakers": [{"name": "Natalie", "g": "f"}, {"name": "Greg", "g": "m"}], "lines": [{"s": 1, "en": "So, Natalie, we're thrilled you're interested. Did you get a chance to go over the offer we sent?", "pt": "Então, Natalie, estamos muito felizes com seu interesse. Você teve a chance de analisar a proposta que enviamos?"}, {"s": 0, "en": "I did, thank you. I'm genuinely excited about the role, but I have to be upfront: the base salary is lower than I expected.", "pt": "Analisei, obrigada. Estou realmente animada com a vaga, mas preciso ser franca: o salário-base está abaixo do que eu esperava."}, {"s": 1, "en": "I see. Well, we put it together based on market data for this level, so there isn't a ton of wiggle room.", "pt": "Entendo. Bom, nós montamos a proposta com base em dados de mercado para esse nível, então não há muita margem de manobra."}, {"s": 0, "en": "I understand. Then again, the role you described is closer to a senior position. I'd be leading a team of six from day one.", "pt": "Entendo. Por outro lado, a função que vocês descreveram está mais para um cargo sênior. Eu lideraria uma equipe de seis pessoas desde o primeiro dia."}, {"s": 1, "en": "That's... a fair observation. What number did you have in mind?", "pt": "Isso é... uma observação justa. Que valor você tinha em mente?"}, {"s": 0, "en": "Something around fifteen percent higher. That's in line with what I'm being offered elsewhere, to be honest.", "pt": "Algo em torno de quinze por cento a mais. Isso está de acordo com o que estão me oferecendo em outros lugares, para ser sincera."}, {"s": 1, "en": "Fifteen is a stretch. I'd have to run it by the finance team, and I can't make any promises.", "pt": "Quinze é puxado. Eu teria que consultar a equipe financeira, e não posso prometer nada."}, {"s": 0, "en": "Of course. And if the base is set in stone, I'd be open to talking about a signing bonus or extra vacation days.", "pt": "Claro. E se o salário-base for inegociável, eu estaria aberta a conversar sobre um bônus de contratação ou dias extras de férias."}, {"s": 1, "en": "Now that's something I can work with. A signing bonus comes out of a different budget.", "pt": "Bom, isso já é algo com que eu consigo trabalhar. Um bônus de contratação sai de outro orçamento."}, {"s": 0, "en": "Great. I just want to make sure I'm starting off on the right foot, without feeling shortchanged six months down the line.", "pt": "Ótimo. Só quero ter certeza de que estou começando com o pé direito, sem me sentir lesada daqui a seis meses."}, {"s": 1, "en": "Totally understandable. Let me talk to finance and get back to you by Thursday. Sound good?", "pt": "Totalmente compreensível. Deixa eu falar com o financeiro e te dou um retorno até quinta. Pode ser?"}, {"s": 0, "en": "Sounds perfect. And just so you know, you're my first choice. I'd really like to make this work.", "pt": "Perfeito. E só pra você saber, vocês são minha primeira opção. Eu realmente gostaria que isso desse certo."}], "questions": [{"q": "Qual argumento Natalie usa para justificar um salário maior?", "options": ["Ela tem mais anos de experiência que os outros candidatos", "As responsabilidades da vaga são de nível sênior", "O custo de vida na cidade aumentou"], "answer": 1}, {"q": "Por que Greg se mostra mais receptivo à ideia do bônus?", "options": ["Porque o bônus é pago com um orçamento diferente", "Porque Natalie ameaçou recusar a proposta", "Porque ele não precisa consultar ninguém sobre salários"], "answer": 0}, {"q": "O que se pode inferir sobre a estratégia de Natalie no final?", "options": ["Ela está blefando e pretende aceitar outra oferta", "Ela desistiu de negociar o salário", "Ela é firme, mas sinaliza interesse para manter a negociação positiva"], "answer": 2}]}, {"id": "dC1-3", "level": "C1", "title": "Arguing About a Film", "titlePt": "Discutindo sobre um filme", "setting": "Dois amigos saem do cinema e discordam sobre um longo filme de arte que acabaram de ver.", "speakers": [{"name": "Jess", "g": "f"}, {"name": "Lucas", "g": "m"}], "lines": [{"s": 0, "en": "Okay, be honest. You hated it, didn't you? You had that look on your face the entire second half.", "pt": "Tá, seja sincero. Você odiou, né? Você ficou com aquela cara durante a segunda metade inteira."}, {"s": 1, "en": "Hated is a strong word. Let's just say it didn't live up to the hype. Three hours, Jess. Three hours!", "pt": "Odiar é uma palavra forte. Digamos que não fez jus ao hype. Três horas, Jess. Três horas!"}, {"s": 0, "en": "But that's the whole point! The slowness is deliberate. It's supposed to make you feel the character's isolation.", "pt": "Mas é justamente essa a ideia! A lentidão é proposital. É pra você sentir o isolamento do personagem."}, {"s": 1, "en": "Oh, I felt isolated, all right. Mostly from my will to live.", "pt": "Ah, eu me senti isolado, sim. Principalmente da minha vontade de viver."}, {"s": 0, "en": "Very funny. Come on, you can't tell me the cinematography wasn't stunning. That shot of the lighthouse in the storm?", "pt": "Muito engraçado. Ah, vai, você não vai me dizer que a fotografia não era deslumbrante. Aquela cena do farol na tempestade?"}, {"s": 1, "en": "Okay, I'll give you that. It looked gorgeous. But a pretty picture doesn't make up for a story that goes nowhere.", "pt": "Tá, isso eu admito. Era lindo de ver. Mas uma imagem bonita não compensa uma história que não vai a lugar nenhum."}, {"s": 0, "en": "It goes somewhere! The ending ties everything together, if you were paying attention, which clearly you weren't.", "pt": "Vai a algum lugar, sim! O final amarra tudo, se você estivesse prestando atenção, o que claramente não estava."}, {"s": 1, "en": "I was paying attention. I just thought the ending was a cop-out. Leaving everything open isn't deep, it's lazy.", "pt": "Eu estava prestando atenção. Só achei o final uma saída fácil. Deixar tudo em aberto não é profundo, é preguiça."}, {"s": 0, "en": "Wow. Remind me never to take you to an art film again.", "pt": "Nossa. Me lembra de nunca mais te levar pra ver um filme de arte."}, {"s": 1, "en": "Deal. Next time I'm picking, and there will be explosions.", "pt": "Combinado. Da próxima vez eu escolho, e vai ter explosão."}, {"s": 0, "en": "Fine. But I'm bringing a book.", "pt": "Tá bom. Mas eu vou levar um livro."}], "questions": [{"q": "O que Lucas quer dizer com 'Mostly from my will to live'?", "options": ["Que o filme o deixou emocionado de verdade", "Que o filme foi tão entediante que virou um sofrimento", "Que ele se identificou com o personagem principal"], "answer": 1}, {"q": "Em que ponto Lucas concorda com Jess?", "options": ["A fotografia do filme era muito bonita", "O final do filme era bem resolvido", "A duração do filme era adequada"], "answer": 0}, {"q": "Qual é o tom da conversa no final?", "options": ["Uma briga séria que pode abalar a amizade", "Uma reconciliação em que Lucas muda de opinião", "Uma provocação bem-humorada entre amigos"], "answer": 2}]}, {"id": "dC1-4", "level": "C1", "title": "The Noisy Ocean", "titlePt": "O oceano barulhento", "setting": "Em um podcast de ciência, o apresentador entrevista uma bióloga marinha que estuda o som no fundo do mar.", "speakers": [{"name": "Helena", "g": "f"}, {"name": "Kevin", "g": "m"}], "lines": [{"s": 1, "en": "Welcome back to the show. My guest today studies something most of us never think about: the sounds of the deep ocean. Helena, thanks for coming on.", "pt": "Bem-vindos de volta ao programa. Minha convidada de hoje estuda algo em que quase ninguém pensa: os sons do fundo do oceano. Helena, obrigado por vir."}, {"s": 0, "en": "Thanks for having me. And you're right, most people assume the deep ocean is silent. It's actually incredibly noisy down there.", "pt": "Obrigada pelo convite. E você tem razão, a maioria das pessoas acha que o fundo do oceano é silencioso. Na verdade, é incrivelmente barulhento lá embaixo."}, {"s": 1, "en": "Noisy how? What are we talking about, whales singing?", "pt": "Barulhento como? Do que estamos falando, baleias cantando?"}, {"s": 0, "en": "Whales, sure, but also shrimp, fish, shifting ice, earthquakes. And increasingly, us. Shipping traffic has turned the volume way up.", "pt": "Baleias, claro, mas também camarões, peixes, gelo se movendo, terremotos. E, cada vez mais, nós. O tráfego de navios aumentou muito o volume."}, {"s": 1, "en": "So that's where your research comes in. You're looking at how that noise affects marine life?", "pt": "Então é aí que entra a sua pesquisa. Você estuda como esse barulho afeta a vida marinha?"}, {"s": 0, "en": "Exactly. We've found that some whales have to call louder and longer just to be heard. It's like trying to talk at a rock concert.", "pt": "Exatamente. Descobrimos que algumas baleias precisam chamar mais alto e por mais tempo só para serem ouvidas. É como tentar conversar num show de rock."}, {"s": 1, "en": "That sounds exhausting. Does it actually harm them, or is it more of an inconvenience?", "pt": "Parece exaustivo. Isso realmente as prejudica, ou é mais um incômodo?"}, {"s": 0, "en": "That's the million-dollar question. The early data suggest it stresses them out and may interfere with feeding, but we're not there yet.", "pt": "Essa é a pergunta de um milhão de dólares. Os dados preliminares sugerem que isso as estressa e pode atrapalhar a alimentação, mas ainda não temos certeza."}, {"s": 1, "en": "And is there anything we can actually do about it, short of banning ships altogether?", "pt": "E existe algo que a gente possa fazer, sem chegar a proibir os navios de vez?"}, {"s": 0, "en": "Surprisingly, yes. If ships slow down by even a few knots, the noise drops dramatically. It's one of the rare easy wins in conservation.", "pt": "Surpreendentemente, sim. Se os navios reduzirem a velocidade em apenas alguns nós, o barulho cai drasticamente. É uma das raras vitórias fáceis na conservação."}, {"s": 1, "en": "Huh. So the solution is basically just, take it easy?", "pt": "Hum. Então a solução é basicamente ir com calma?"}, {"s": 0, "en": "Pretty much. Though convincing shipping companies to lose time and money is a whole other story.", "pt": "Basicamente. Embora convencer as empresas de navegação a perder tempo e dinheiro seja outra história."}], "questions": [{"q": "Segundo Helena, qual é uma ideia equivocada comum sobre o fundo do oceano?", "options": ["Que ele é silencioso", "Que nele não há vida", "Que ele é frio demais para as baleias"], "answer": 0}, {"q": "Como Helena descreve o nível de certeza sobre os danos às baleias?", "options": ["Já está comprovado que o ruído mata as baleias", "Há indícios de estresse, mas ainda não há conclusões definitivas", "Não há nenhuma evidência de impacto"], "answer": 1}, {"q": "O que Helena sugere com a última frase?", "options": ["Que as empresas já aceitaram reduzir a velocidade", "Que a solução técnica é cara e complicada", "Que a solução é simples, mas enfrenta resistência econômica"], "answer": 2}]}, {"id": "dC1-5", "level": "C1", "title": "Moving Abroad?", "titlePt": "Mudar para o exterior?", "setting": "Um casal discute se deve aceitar uma proposta de emprego que os levaria a morar em Lisboa.", "speakers": [{"name": "Sofia", "g": "f"}, {"name": "Daniel", "g": "m"}], "lines": [{"s": 1, "en": "So I got the email today. They want an answer about the Lisbon position by the end of the month.", "pt": "Então, recebi o e-mail hoje. Eles querem uma resposta sobre a vaga em Lisboa até o fim do mês."}, {"s": 0, "en": "The end of the month? That's in, what, three weeks? No pressure, then.", "pt": "Até o fim do mês? Isso é daqui a, sei lá, três semanas? Sem pressão nenhuma, né."}, {"s": 1, "en": "I know, it's fast. But I keep thinking, if we don't do it now, we'll never do it. We'll just keep putting it off.", "pt": "Eu sei, é rápido. Mas fico pensando: se a gente não fizer isso agora, nunca vai fazer. Vamos só ficar adiando."}, {"s": 0, "en": "I'm not saying no. It's just that I've finally got my practice off the ground here. I'd be starting from scratch.", "pt": "Não estou dizendo não. É que finalmente consegui fazer meu consultório decolar aqui. Eu estaria começando do zero."}, {"s": 1, "en": "I know, and I don't take that lightly. But you could keep working remotely with some of your clients, couldn't you?", "pt": "Eu sei, e não encaro isso de forma leviana. Mas você poderia continuar atendendo alguns clientes à distância, não poderia?"}, {"s": 0, "en": "Some of them, maybe. But half my work is in person. And then there's my mom. She's not getting any younger.", "pt": "Alguns, talvez. Mas metade do meu trabalho é presencial. E tem a minha mãe. Ela não está ficando mais jovem."}, {"s": 1, "en": "That's fair. We could come back a few times a year. And honestly, the flights aren't that bad.", "pt": "É justo. A gente poderia voltar algumas vezes por ano. E, sinceramente, os voos não são tão ruins."}, {"s": 0, "en": "A few times a year isn't the same as being twenty minutes away when something goes wrong, Dan.", "pt": "Algumas vezes por ano não é a mesma coisa que estar a vinte minutos de distância quando algo dá errado, Dan."}, {"s": 1, "en": "No, it's not. You're right. What if we made it a two-year thing? A trial run, with a clear plan to come back if it's not working.", "pt": "Não, não é. Você tem razão. E se a gente fizesse isso por dois anos? Um teste, com um plano claro de voltar se não estiver dando certo."}, {"s": 0, "en": "A trial run... I could live with that, I think. As long as coming back is a real option, not just something you say to win me over.", "pt": "Um teste... Acho que eu toparia isso. Desde que voltar seja uma opção real, e não só algo que você diz pra me convencer."}, {"s": 1, "en": "It's a real option. I promise. I don't want to drag you somewhere you'll end up resenting.", "pt": "É uma opção real. Eu prometo. Não quero te arrastar para um lugar que você vai acabar odiando."}, {"s": 0, "en": "Okay. Let me sleep on it. But for the record, I'm a lot closer to yes than I was this morning.", "pt": "Tá bom. Deixa eu pensar com calma. Mas, só pra constar, estou bem mais perto do sim do que hoje de manhã."}], "questions": [{"q": "Qual é a principal preocupação de Sofia em relação à mudança?", "options": ["Ela não gosta de Lisboa", "Ela perderia o negócio que construiu e ficaria longe da mãe", "Ela acha que o salário de Daniel seria baixo"], "answer": 1}, {"q": "O que Sofia insinua ao dizer 'not just something you say to win me over'?", "options": ["Que ela suspeita que a promessa de voltar possa ser só um argumento para convencê-la", "Que ela quer que Daniel a conquiste de novo", "Que ela já decidiu não ir"], "answer": 0}, {"q": "Como Sofia está ao final da conversa?", "options": ["Decidida a recusar a mudança", "Irritada com a pressão de Daniel", "Mais inclinada a aceitar, mas ainda sem decisão final"], "answer": 2}]}, {"id": "dC1-6", "level": "C1", "title": "Priced Out", "titlePt": "Sem condições de comprar", "setting": "Em um programa de rádio com participação dos ouvintes, um professor liga para falar sobre o preço dos imóveis.", "speakers": [{"name": "Monica", "g": "f"}, {"name": "Ray", "g": "m"}], "lines": [{"s": 0, "en": "You're on the air with City Talk. Our topic tonight is housing prices. Go ahead, caller, you're on.", "pt": "Você está no ar no City Talk. Nosso tema hoje é o preço dos imóveis. Pode falar, ouvinte, você está no ar."}, {"s": 1, "en": "Hi, Monica, long-time listener. My name's Ray, and I'm a teacher. I've been renting for twelve years and I've basically given up on buying.", "pt": "Oi, Monica, ouvinte antigo. Meu nome é Ray, sou professor. Moro de aluguel há doze anos e basicamente desisti de comprar."}, {"s": 0, "en": "I'm sorry to hear that, Ray, but you're definitely not alone. What's been the biggest obstacle for you?", "pt": "Sinto muito ouvir isso, Ray, mas você com certeza não está sozinho. Qual tem sido o maior obstáculo pra você?"}, {"s": 1, "en": "The down payment, hands down. Every time I get close, prices jump again. It's like chasing a train that keeps speeding up.", "pt": "A entrada, sem dúvida. Toda vez que chego perto, os preços sobem de novo. É como correr atrás de um trem que não para de acelerar."}, {"s": 0, "en": "That's a feeling a lot of our callers have described tonight. Have you looked into any of the first-time buyer programs?", "pt": "Esse é um sentimento que muitos ouvintes descreveram hoje. Você já pesquisou algum programa para quem compra o primeiro imóvel?"}, {"s": 1, "en": "I have, but the income limits are ridiculous. I make too much to qualify and nowhere near enough to actually buy.", "pt": "Já, mas os limites de renda são ridículos. Eu ganho demais para me qualificar e muito pouco para conseguir comprar de fato."}, {"s": 0, "en": "Ah, the famous missing middle. You make enough to be ignored, but not enough to get ahead.", "pt": "Ah, a famosa classe média esquecida. Você ganha o bastante para ser ignorado, mas não o bastante para progredir."}, {"s": 1, "en": "Exactly. And meanwhile, investors are snapping up entire blocks and turning them into short-term rentals.", "pt": "Exatamente. E, enquanto isso, investidores estão comprando quarteirões inteiros e transformando tudo em aluguel por temporada."}, {"s": 0, "en": "Some would argue that's just the free market at work. What would you say to them?", "pt": "Alguns diriam que isso é só o livre mercado funcionando. O que você diria a eles?"}, {"s": 1, "en": "I'd say the market isn't very free if the people who teach your kids can't afford to live in the same town.", "pt": "Eu diria que o mercado não é tão livre assim se as pessoas que dão aula para os seus filhos não podem pagar para morar na mesma cidade."}, {"s": 0, "en": "That's a powerful point to end on. Thanks for calling in, Ray, and good luck. Let's take another call.", "pt": "Que argumento forte para encerrar. Obrigada por ligar, Ray, e boa sorte. Vamos para a próxima ligação."}], "questions": [{"q": "Por que Ray não consegue participar dos programas para quem compra o primeiro imóvel?", "options": ["Porque ele não tem emprego fixo", "Porque ele já tem um imóvel", "Porque ele ganha acima do limite, mas não o suficiente para comprar"], "answer": 2}, {"q": "O que significa a comparação com 'chasing a train that keeps speeding up'?", "options": ["Que os preços sobem mais rápido do que ele consegue economizar", "Que ele perde muito tempo no transporte público", "Que o mercado está prestes a cair"], "answer": 0}, {"q": "Qual é a atitude de Ray em relação ao argumento do 'livre mercado'?", "options": ["Ele concorda que os investidores estão no seu direito", "Ele critica a ideia, dizendo que o sistema exclui trabalhadores essenciais", "Ele não tem opinião formada sobre o assunto"], "answer": 1}]}, {"id": "dC1-7", "level": "C1", "title": "Launch Post-Mortem", "titlePt": "Análise de um lançamento fracassado", "setting": "Uma gerente de produto e um engenheiro analisam por que o lançamento de um aplicativo deu errado.", "speakers": [{"name": "Olivia", "g": "f"}, {"name": "Ben", "g": "m"}], "lines": [{"s": 0, "en": "Alright, let's rip the band-aid off. The launch numbers are in, and they're, well, not great. About a third of what we projected.", "pt": "Certo, vamos arrancar o curativo de uma vez. Os números do lançamento saíram e, bom, não estão nada bons. Cerca de um terço do que projetamos."}, {"s": 1, "en": "Ouch. I figured it was bad from the support tickets, but a third? That's rough.", "pt": "Ai. Pelos chamados de suporte eu imaginei que estava ruim, mas um terço? Isso é pesado."}, {"s": 0, "en": "The point of this meeting isn't to point fingers. I want to understand what went wrong so we don't repeat it.", "pt": "O objetivo desta reunião não é apontar culpados. Quero entender o que deu errado para não repetirmos."}, {"s": 1, "en": "Okay, then I'll go first. We rushed it. Engineering flagged the sync bug two weeks before launch, and we shipped anyway.", "pt": "Tá, então eu começo. A gente apressou as coisas. A engenharia apontou o bug de sincronização duas semanas antes do lançamento, e lançamos mesmo assim."}, {"s": 0, "en": "That's fair. That was my call, and in hindsight, it was the wrong one. The deadline felt non-negotiable at the time.", "pt": "É justo. Essa decisão foi minha e, olhando para trás, foi a errada. Na época, o prazo parecia inegociável."}, {"s": 1, "en": "I appreciate you saying that. But to be fair, the bug wasn't the only issue. I'm not sure people even understood what the app was for.", "pt": "Agradeço por você dizer isso. Mas, para ser justo, o bug não foi o único problema. Não sei se as pessoas sequer entenderam para que servia o aplicativo."}, {"s": 0, "en": "Meaning the messaging was off?", "pt": "Quer dizer que a comunicação estava errada?"}, {"s": 1, "en": "Meaning we spent six months building features and maybe six days figuring out how to explain them.", "pt": "Quer dizer que passamos seis meses criando funcionalidades e talvez seis dias pensando em como explicá-las."}, {"s": 0, "en": "Ugh, you're right. Our beta testers loved it, but they were our friends. We were basically preaching to the choir.", "pt": "Ah, você tem razão. Nossos testadores beta adoraram, mas eram nossos amigos. A gente estava basicamente pregando para convertidos."}, {"s": 1, "en": "So, next time, real users earlier, and we don't ship with known bugs just to hit a date.", "pt": "Então, da próxima vez, usuários reais mais cedo, e nada de lançar com bugs conhecidos só para cumprir uma data."}, {"s": 0, "en": "Agreed. Let's write that down before we conveniently forget it in three months.", "pt": "Combinado. Vamos anotar isso antes que a gente convenientemente esqueça daqui a três meses."}], "questions": [{"q": "O que Olivia admite durante a reunião?", "options": ["Que a equipe de engenharia foi a culpada", "Que foi decisão dela lançar o produto mesmo com o bug", "Que os números de lançamento foram melhores que o esperado"], "answer": 1}, {"q": "Segundo Ben, qual foi o problema além do bug?", "options": ["O preço do aplicativo era alto demais", "A equipe não tinha recursos suficientes", "As pessoas não entendiam para que servia o aplicativo"], "answer": 2}, {"q": "O que Olivia sugere com 'before we conveniently forget it in three months'?", "options": ["Que equipes costumam esquecer as lições aprendidas, por isso é preciso registrá-las", "Que ela pretende sair da empresa em três meses", "Que o próximo lançamento será daqui a três meses"], "answer": 0}]}, {"id": "dC1-8", "level": "C1", "title": "Time for a Redesign", "titlePt": "Hora de reformular", "setting": "Um web designer tenta convencer a dona de um pequeno negócio a refazer o site da empresa.", "speakers": [{"name": "Carla", "g": "f"}, {"name": "Ethan", "g": "m"}], "lines": [{"s": 1, "en": "Thanks for meeting with me, Carla. I took a close look at your website, and I'll be honest, a few quick fixes won't cut it.", "pt": "Obrigado por me receber, Carla. Analisei seu site com atenção e, vou ser sincero, uns ajustes rápidos não vão resolver."}, {"s": 0, "en": "I was afraid you'd say that. I was hoping we could just update the photos and call it a day.", "pt": "Eu tinha medo de que você dissesse isso. Estava torcendo para a gente só trocar as fotos e pronto."}, {"s": 1, "en": "We could, but it'd be like painting a house with a cracked foundation. Over half your visitors leave within ten seconds.", "pt": "Até daria, mas seria como pintar uma casa com a fundação rachada. Mais da metade dos seus visitantes sai em menos de dez segundos."}, {"s": 0, "en": "Ten seconds? That seems a bit dramatic. People find us through word of mouth anyway.", "pt": "Dez segundos? Parece meio exagerado. As pessoas chegam até nós pelo boca a boca, de qualquer forma."}, {"s": 1, "en": "They do, and that's great. But when a friend recommends you, people look you up on their phone. And on mobile, your site barely works.", "pt": "Chegam, e isso é ótimo. Mas quando um amigo recomenda você, as pessoas te procuram no celular. E no celular seu site mal funciona."}, {"s": 0, "en": "Huh. I've honestly never checked it on my phone.", "pt": "Hum. Para ser sincera, nunca olhei no meu celular."}, {"s": 1, "en": "Most owners haven't. Take a look now, actually. Try to find your opening hours.", "pt": "A maioria dos donos nunca olhou. Dá uma olhada agora, inclusive. Tenta achar o seu horário de funcionamento."}, {"s": 0, "en": "Okay... hang on... oh, wow. The menu covers half the screen. That's embarrassing.", "pt": "Tá... espera aí... nossa. O menu cobre metade da tela. Que vergonha."}, {"s": 1, "en": "It's an easy fix with a proper redesign. And I'm not suggesting anything fancy. Clean, fast, easy to book.", "pt": "Isso se resolve fácil com uma reformulação bem feita. E não estou sugerindo nada sofisticado. Limpo, rápido, fácil de agendar."}, {"s": 0, "en": "Alright, you've made your point. But I'm a small business. What kind of budget are we talking about?", "pt": "Tá bom, você me convenceu. Mas eu sou um pequeno negócio. De que orçamento estamos falando?"}, {"s": 1, "en": "Let me put together two options, a basic one and a full package. You can decide what makes sense, no pressure.", "pt": "Deixa eu montar duas opções, uma básica e um pacote completo. Você decide o que faz sentido, sem pressão."}], "questions": [{"q": "Qual era a expectativa inicial de Carla?", "options": ["Fazer apenas pequenas mudanças, como trocar as fotos", "Contratar uma reformulação completa do site", "Fechar a loja virtual"], "answer": 0}, {"q": "O que convence Carla de que há um problema?", "options": ["Os dados de visitas que Ethan mostra em um relatório", "Uma reclamação de um cliente", "Ver pessoalmente como o site funciona mal no celular"], "answer": 2}, {"q": "Qual é a estratégia de Ethan no final?", "options": ["Pressionar Carla a fechar o pacote mais caro imediatamente", "Oferecer opções de preço e deixar a decisão com ela", "Oferecer o serviço de graça"], "answer": 1}]}, {"id": "dC2-1", "level": "C2", "title": "The Bridge to Nowhere", "titlePt": "A ponte que não chega", "setting": "Uma jornalista entrevista um vice-prefeito sobre o atraso e o estouro de orçamento na obra de uma ponte.", "speakers": [{"name": "Hannah", "g": "f"}, {"name": "Victor", "g": "m"}], "lines": [{"s": 0, "en": "Mr. Hale, thanks for making time. I'll cut to the chase: the bridge project is eighteen months late and forty percent over budget. How did that happen?", "pt": "Sr. Hale, obrigada por arrumar um tempo. Vou direto ao ponto: a obra da ponte está dezoito meses atrasada e quarenta por cento acima do orçamento. Como isso aconteceu?"}, {"s": 1, "en": "Well, I'd push back a little on the framing. What we've seen is the cumulative effect of supply chain disruptions nobody could have reasonably foreseen.", "pt": "Bom, eu contestaria um pouco essa forma de colocar. O que vimos foi o efeito acumulado de problemas na cadeia de suprimentos que ninguém poderia razoavelmente ter previsto."}, {"s": 0, "en": "Nobody? Your own engineers flagged those risks in a report two years ago. It's a matter of public record.", "pt": "Ninguém? Seus próprios engenheiros apontaram esses riscos num relatório dois anos atrás. Isso é de conhecimento público."}, {"s": 1, "en": "That report outlined a range of scenarios. Not every scenario is a forecast, and hindsight, as they say, is twenty-twenty.", "pt": "Aquele relatório descrevia uma série de cenários. Nem todo cenário é uma previsão e, como dizem, depois que acontece é fácil ser profeta."}, {"s": 0, "en": "With respect, that sounds like a very polished way of saying the warnings were ignored.", "pt": "Com todo o respeito, isso soa como uma forma muito elegante de dizer que os alertas foram ignorados."}, {"s": 1, "en": "They weren't ignored. They were weighed against other priorities. Had we delayed the project back then, the costs would've been even higher.", "pt": "Eles não foram ignorados. Foram ponderados em relação a outras prioridades. Se tivéssemos adiado a obra naquela época, os custos teriam sido ainda maiores."}, {"s": 0, "en": "That's a hypothetical you can't prove. What I can prove is that residents have been detouring forty minutes a day for over a year.", "pt": "Isso é uma hipótese que o senhor não pode provar. O que eu posso provar é que os moradores fazem um desvio de quarenta minutos por dia há mais de um ano."}, {"s": 1, "en": "And I don't for a second dismiss that frustration. I drive that detour myself, believe it or not.", "pt": "E eu não desconsidero essa frustração nem por um segundo. Eu mesmo faço esse desvio, acredite se quiser."}, {"s": 0, "en": "I'm sure they'll find that comforting. So, when will the bridge actually open? And I'd like a date, not a season.", "pt": "Tenho certeza de que eles vão achar isso muito reconfortante. Então, quando a ponte vai de fato abrir? E eu gostaria de uma data, não de uma estação do ano."}, {"s": 1, "en": "Our current projection is the end of next spring, barring any unforeseen...", "pt": "Nossa projeção atual é o fim da próxima primavera, salvo algum imprevisto..."}, {"s": 0, "en": "There it is again. Unforeseen. Can you see why people are starting to tune out when they hear that word?", "pt": "Lá vem de novo. Imprevisto. O senhor entende por que as pessoas estão começando a se desligar quando ouvem essa palavra?"}, {"s": 1, "en": "I can. And I take the point. What I can commit to is monthly public updates, so nobody's left in the dark again.", "pt": "Entendo. E aceito a crítica. O que posso garantir são atualizações públicas mensais, para que ninguém fique no escuro de novo."}, {"s": 0, "en": "Then I'll hold you to that. Monthly, starting when?", "pt": "Então vou cobrar isso do senhor. Mensais, a partir de quando?"}, {"s": 1, "en": "Starting next month. You have my word, and you can quote me on it.", "pt": "A partir do mês que vem. A senhora tem a minha palavra, e pode me citar."}], "questions": [{"q": "O que Hannah insinua sobre a explicação de Victor para os atrasos?", "options": ["Que ela é convincente e bem fundamentada", "Que é uma forma elegante de esconder que os alertas foram ignorados", "Que a culpa é apenas dos engenheiros"], "answer": 1}, {"q": "Qual é o tom de 'I'm sure they'll find that comforting'?", "options": ["Irônico, sugerindo que o comentário de Victor não ajuda em nada", "Sincero, elogiando a empatia de Victor", "Neutro, apenas registrando a informação"], "answer": 0}, {"q": "Por que Hannah interrompe Victor quando ele fala da previsão de abertura?", "options": ["Porque ela já sabia a data exata", "Porque ele estava falando rápido demais", "Porque ele volta a usar a desculpa dos imprevistos que ela vinha criticando"], "answer": 2}]}, {"id": "dC2-2", "level": "C2", "title": "Reading the Results", "titlePt": "Interpretando os resultados", "setting": "Um médico explica com cuidado o resultado de um exame de imagem a uma paciente preocupada.", "speakers": [{"name": "Grace", "g": "f"}, {"name": "Alan", "g": "m"}], "lines": [{"s": 1, "en": "Grace, thanks for coming back in. I've gone over your scan results with the radiologist, and I want to walk you through them carefully.", "pt": "Grace, obrigado por voltar. Revisei os resultados do seu exame com o radiologista e quero explicar tudo com calma."}, {"s": 0, "en": "That doesn't sound like good news. Just give it to me straight, please. I've been bracing myself all week.", "pt": "Isso não parece boa notícia. Fala logo, sem rodeios, por favor. Passei a semana inteira me preparando."}, {"s": 1, "en": "Fair enough. There's a small nodule on your thyroid. Now, before you jump to conclusions, the vast majority of these turn out to be benign.", "pt": "Justo. Há um pequeno nódulo na sua tireoide. Agora, antes de tirar conclusões precipitadas, a grande maioria desses nódulos acaba sendo benigna."}, {"s": 0, "en": "The vast majority. Which means some aren't. What are we talking about, percentage-wise?", "pt": "A grande maioria. O que significa que alguns não são. De que porcentagem estamos falando?"}, {"s": 1, "en": "Somewhere around five to ten percent, depending on the study. And yours has several features that, frankly, put it at the reassuring end of that range.", "pt": "Algo entre cinco e dez por cento, dependendo do estudo. E o seu tem várias características que, francamente, o colocam no lado mais tranquilizador dessa faixa."}, {"s": 0, "en": "Okay. Reassuring is good. But I'm sensing a 'but' coming.", "pt": "Tá. Tranquilizador é bom. Mas estou sentindo que vem um 'mas' aí."}, {"s": 1, "en": "Not a but so much as an and. What I'd recommend is a fine-needle biopsy, just so we're not relying on educated guesses.", "pt": "Não é bem um 'mas', é mais um 'e'. O que eu recomendaria é uma punção com agulha fina, só para não dependermos de suposições, por mais embasadas que sejam."}, {"s": 0, "en": "Is that really necessary? If it's probably nothing, couldn't we just keep an eye on it?", "pt": "Isso é mesmo necessário? Se provavelmente não é nada, não daria só para ficar de olho?"}, {"s": 1, "en": "That's a perfectly reasonable option, and some doctors would go that way. Where I land is that peace of mind is worth a ten-minute procedure.", "pt": "É uma opção perfeitamente razoável, e alguns médicos seguiriam esse caminho. A minha posição é que a tranquilidade vale um procedimento de dez minutos."}, {"s": 0, "en": "Peace of mind for you or for me?", "pt": "Tranquilidade para você ou para mim?"}, {"s": 1, "en": "Ha, fair question. For both of us, honestly. But it's your call, and I'll support either choice.", "pt": "Ha, pergunta justa. Para nós dois, sinceramente. Mas a decisão é sua, e vou apoiar qualquer escolha."}, {"s": 0, "en": "What scares me, I guess, isn't the needle. It's the waiting for results afterward.", "pt": "Acho que o que me assusta não é a agulha. É esperar o resultado depois."}, {"s": 1, "en": "That's completely understandable. It's usually under a week, and I'll call you myself the moment they're in, rather than leaving you to check a portal.", "pt": "É totalmente compreensível. Normalmente leva menos de uma semana, e eu mesmo te ligo assim que sair, em vez de deixar você ficar conferindo um portal."}, {"s": 0, "en": "Alright. Let's do it. Better to know than to spend months wondering.", "pt": "Tudo bem. Vamos fazer. Melhor saber do que passar meses na dúvida."}], "questions": [{"q": "Como o médico apresenta o diagnóstico?", "options": ["De forma alarmista, enfatizando o risco de câncer", "De forma vaga, evitando dar números", "Com cautela e dados, destacando que o caso parece tranquilizador"], "answer": 2}, {"q": "O que Grace insinua com 'Peace of mind for you or for me?'", "options": ["Que a biópsia talvez sirva mais para tranquilizar o médico do que a ela", "Que ela não confia no laudo do radiologista", "Que ela quer uma segunda opinião"], "answer": 0}, {"q": "Segundo Grace, o que mais a assusta?", "options": ["A dor do procedimento", "A espera pelo resultado", "O custo do exame"], "answer": 1}]}, {"id": "dC2-3", "level": "C2", "title": "Thesis Feedback", "titlePt": "Orientação de tese", "setting": "Uma professora orientadora dá um retorno franco a um aluno de pós-graduação sobre o rascunho da tese dele.", "speakers": [{"name": "Margaret", "g": "f"}, {"name": "Julian", "g": "m"}], "lines": [{"s": 0, "en": "Julian, come on in. I've read the full draft, and before anything else, let me say there's some genuinely original thinking in here.", "pt": "Julian, pode entrar. Li o rascunho completo e, antes de mais nada, quero dizer que há ideias realmente originais aqui."}, {"s": 1, "en": "Thank you. Though I sense that's the spoonful of sugar before the medicine.", "pt": "Obrigado. Mas sinto que isso é o docinho antes do remédio amargo."}, {"s": 0, "en": "You're not wrong. What's missing, to put it bluntly, is a coherent argument tying the chapters together. Right now it reads like four separate essays.", "pt": "Você não está errado. O que falta, para ser direta, é um argumento coerente ligando os capítulos. Do jeito que está, parecem quatro ensaios separados."}, {"s": 1, "en": "Four essays? I thought the theme of migration ran through all of them pretty clearly.", "pt": "Quatro ensaios? Achei que o tema da migração atravessava todos eles de forma bem clara."}, {"s": 0, "en": "It's there, but a theme isn't an argument. What is it you're actually claiming? If I asked you in one sentence, could you tell me?", "pt": "Ele está lá, mas tema não é argumento. O que é que você está de fato defendendo? Se eu pedisse em uma frase, você conseguiria me dizer?"}, {"s": 1, "en": "Um... that migration reshaped urban identity in the postwar period?", "pt": "Hum... que a migração transformou a identidade urbana no pós-guerra?"}, {"s": 0, "en": "See, that's a topic dressed up as a claim. Reshaped how? For whom? And compared to what?", "pt": "Viu? Isso é um tema fantasiado de tese. Transformou como? Para quem? E em comparação com o quê?"}, {"s": 1, "en": "Okay, that stings a bit. But I take your point. I suppose I've been circling around it rather than committing.", "pt": "Tá, isso dói um pouco. Mas entendo o que você quer dizer. Acho que venho rodeando a questão em vez de me comprometer com uma posição."}, {"s": 0, "en": "Which is perfectly normal at this stage. Rarely does a first draft know what it's about. That's what revision is for.", "pt": "O que é perfeitamente normal nesta fase. Raramente um primeiro rascunho sabe do que trata. É para isso que serve a revisão."}, {"s": 1, "en": "So should I rewrite the whole thing? The deadline's in four months.", "pt": "Então eu deveria reescrever tudo? O prazo é daqui a quatro meses."}, {"s": 0, "en": "Not at all. Most of the research holds up beautifully. What you need is a stronger introduction and conclusion, and some reframing in chapter three.", "pt": "De jeito nenhum. A maior parte da pesquisa se sustenta muito bem. O que você precisa é de uma introdução e uma conclusão mais fortes, e de um novo enquadramento no capítulo três."}, {"s": 1, "en": "Chapter three was the one I was proudest of, ironically.", "pt": "Ironicamente, o capítulo três era o que mais me orgulhava."}, {"s": 0, "en": "It's also the one with the most potential. Bring me a one-page statement of your argument by next Friday, and we'll take it from there.", "pt": "Ele também é o que tem mais potencial. Me traga uma página com o seu argumento até a próxima sexta, e seguimos a partir daí."}, {"s": 1, "en": "One page. Got it. Painful, but probably exactly what I need.", "pt": "Uma página. Entendido. Doloroso, mas provavelmente é exatamente do que eu preciso."}], "questions": [{"q": "O que Julian quer dizer com 'the spoonful of sugar before the medicine'?", "options": ["Que ele espera uma crítica depois do elogio inicial", "Que ele está se sentindo mal", "Que ele acredita que a tese está perfeita"], "answer": 0}, {"q": "Qual é a principal crítica da professora?", "options": ["A pesquisa é insuficiente e mal documentada", "Falta à tese um argumento central claro que una os capítulos", "O tema da migração não é relevante"], "answer": 1}, {"q": "Qual é a atitude da professora em relação ao trabalho de Julian?", "options": ["Ela acha que ele deve recomeçar do zero", "Ela é indiferente ao resultado", "Ela é exigente, mas encorajadora, e vê potencial no trabalho"], "answer": 2}]}, {"id": "dC2-4", "level": "C2", "title": "Clearing the Air", "titlePt": "Colocando os pingos nos is", "setting": "Uma mediadora do RH conversa com um funcionário sobre o conflito dele com uma colega de equipe.", "speakers": [{"name": "Denise", "g": "f"}, {"name": "Paul", "g": "m"}], "lines": [{"s": 0, "en": "Paul, thanks for agreeing to talk. I want to be clear this isn't disciplinary. I'm just trying to understand what's been going on between you and Karen.", "pt": "Paul, obrigada por aceitar conversar. Quero deixar claro que isso não é disciplinar. Só estou tentando entender o que vem acontecendo entre você e a Karen."}, {"s": 1, "en": "Honestly? I'm not sure there's much to understand. She's been undermining me in meetings for months.", "pt": "Sinceramente? Não sei se há muito o que entender. Ela vem me minando nas reuniões há meses."}, {"s": 0, "en": "Undermining is a strong word. Can you give me a concrete example?", "pt": "Minar é uma palavra forte. Você pode me dar um exemplo concreto?"}, {"s": 1, "en": "Last Tuesday. I presented the budget plan, and she jumped in with, and I quote, a few small corrections, in front of the entire leadership team.", "pt": "Terça passada. Eu apresentei o plano orçamentário e ela se meteu com, nas palavras dela, umas pequenas correções, na frente de toda a diretoria."}, {"s": 0, "en": "Were the corrections accurate?", "pt": "As correções estavam certas?"}, {"s": 1, "en": "That's beside the point. Well, two of them were. But she could've come to me beforehand instead of making me look incompetent.", "pt": "Isso não vem ao caso. Bom, duas estavam. Mas ela podia ter falado comigo antes, em vez de me fazer parecer incompetente."}, {"s": 0, "en": "So it's less about what she said and more about how and where she said it.", "pt": "Então a questão é menos o que ela disse e mais como e onde ela disse."}, {"s": 1, "en": "Exactly. If she'd flagged it privately, I'd have thanked her. What bothers me is that it keeps happening, always in public.", "pt": "Exatamente. Se ela tivesse me avisado em particular, eu teria agradecido. O que me incomoda é que isso continua acontecendo, sempre em público."}, {"s": 0, "en": "That's helpful. For what it's worth, when I spoke to Karen, she said she'd emailed you about the numbers twice and never heard back.", "pt": "Isso ajuda. Só para constar, quando conversei com a Karen, ela disse que te mandou e-mail sobre os números duas vezes e nunca teve resposta."}, {"s": 1, "en": "She... did she? I mean, my inbox has been a disaster since the reorg. It's possible I missed them.", "pt": "Ela... mandou? Quer dizer, minha caixa de entrada está um caos desde a reestruturação. É possível que eu não tenha visto."}, {"s": 0, "en": "I'm not saying that excuses anything. But it might explain why she felt she had no other option.", "pt": "Não estou dizendo que isso justifica tudo. Mas pode explicar por que ela sentiu que não tinha outra opção."}, {"s": 1, "en": "Okay. Point taken. I'm still annoyed, but I can see how it might look from her side.", "pt": "Tá. Entendi o recado. Ainda estou irritado, mas consigo ver como isso pode parecer do ponto de vista dela."}, {"s": 0, "en": "That's all I'm asking. Would you be willing to sit down with her, with me there, and agree on how to handle feedback going forward?", "pt": "É só isso que eu peço. Você toparia sentar com ela, comigo presente, e combinar como lidar com feedbacks daqui pra frente?"}, {"s": 1, "en": "Yeah. Fine. Better that than another passive-aggressive meeting, I suppose.", "pt": "Tá. Tudo bem. Melhor isso do que outra reunião passivo-agressiva, imagino."}], "questions": [{"q": "Qual é o verdadeiro incômodo de Paul em relação a Karen?", "options": ["As correções dela estavam todas erradas", "A forma e o lugar em que ela faz as correções, sempre em público", "Ela ganhou uma promoção que ele queria"], "answer": 1}, {"q": "Que informação Denise traz que muda a perspectiva de Paul?", "options": ["Karen tentou falar com ele por e-mail antes e não obteve resposta", "Karen pediu demissão", "A diretoria elogiou a apresentação de Paul"], "answer": 0}, {"q": "Como Paul reage ao final?", "options": ["Recusa qualquer reunião com Karen", "Pede desculpas formais a Karen imediatamente", "Ainda irritado, aceita uma reunião mediada"], "answer": 2}]}, {"id": "dC2-5", "level": "C2", "title": "Consent on Page Thirty-Two", "titlePt": "Consentimento na página trinta e dois", "setting": "Uma engenheira questiona o diretor de produto sobre um acordo para compartilhar dados de usuários com uma seguradora.", "speakers": [{"name": "Nadia", "g": "f"}, {"name": "Simon", "g": "m"}], "lines": [{"s": 0, "en": "Simon, can I grab you for a second? It's about the data-sharing deal with the insurance partner. I've got serious reservations.", "pt": "Simon, posso falar com você um segundo? É sobre o acordo de compartilhamento de dados com a seguradora parceira. Tenho sérias ressalvas."}, {"s": 1, "en": "I figured you might. Go on, I'm listening. Though I should warn you, the deal's pretty much done.", "pt": "Imaginei que teria. Pode falar, estou ouvindo. Mas já aviso que o acordo está praticamente fechado."}, {"s": 0, "en": "That's precisely what worries me. We'd be passing on users' driving and location data, and most of them have no idea.", "pt": "É exatamente isso que me preocupa. Estaríamos repassando dados de direção e de localização dos usuários, e a maioria nem faz ideia."}, {"s": 1, "en": "It's in the terms of service. Technically, they've consented.", "pt": "Está nos termos de uso. Tecnicamente, eles consentiram."}, {"s": 0, "en": "Technically, yes. But let's not kid ourselves. Nobody reads forty pages of legalese. Consent buried on page thirty-two isn't really consent.", "pt": "Tecnicamente, sim. Mas não vamos nos enganar. Ninguém lê quarenta páginas de juridiquês. Um consentimento enterrado na página trinta e dois não é consentimento de verdade."}, {"s": 1, "en": "I don't disagree in principle. But this partnership keeps the lights on. Without it, we're looking at layoffs, possibly on your team.", "pt": "Em princípio, não discordo. Mas essa parceria é o que paga as contas. Sem ela, vamos ter demissões, possivelmente na sua equipe."}, {"s": 0, "en": "So it's either compromise our users or lose our jobs? That feels like a false choice.", "pt": "Então ou a gente prejudica os usuários ou perde o emprego? Isso me parece um falso dilema."}, {"s": 1, "en": "Then give me a third option. Seriously. I'd take one in a heartbeat.", "pt": "Então me dá uma terceira opção. Sério. Eu aceitaria na hora."}, {"s": 0, "en": "Make it opt-in. Clear language, a real choice, maybe a discount for people who share. Some will say yes, and they'll mean it.", "pt": "Tornar opcional, com adesão voluntária. Linguagem clara, uma escolha real, talvez um desconto para quem compartilhar. Alguns vão dizer sim, e vão estar falando sério."}, {"s": 1, "en": "Opt-in rates are notoriously low. The partner might walk away.", "pt": "As taxas de adesão voluntária são notoriamente baixas. O parceiro pode desistir."}, {"s": 0, "en": "Might. And if this ever leaks, which these things tend to do, it's not just the partner walking away. It's our users.", "pt": "Pode. E se isso vazar algum dia, como essas coisas costumam vazar, não vai ser só o parceiro indo embora. Vão ser os nossos usuários."}, {"s": 1, "en": "Okay. What I can do is take it back to leadership and present opt-in as a counterproposal. No guarantees.", "pt": "Tá bom. O que eu posso fazer é levar isso de volta para a diretoria e apresentar a adesão voluntária como contraproposta. Sem garantias."}, {"s": 0, "en": "That's all I'm asking for. And I'll help build the case with numbers, so it's not just me sounding the alarm.", "pt": "É só isso que eu peço. E vou ajudar a montar a argumentação com números, para não ser só eu dando o alarme."}, {"s": 1, "en": "Good. Because, to be frank, an ethics argument alone won't fly upstairs. A risk argument might.", "pt": "Ótimo. Porque, para ser franco, um argumento ético sozinho não vai colar lá em cima. Um argumento de risco talvez cole."}], "questions": [{"q": "Qual é o argumento central de Nadia contra o acordo?", "options": ["O acordo não traz dinheiro suficiente", "O consentimento dos usuários é apenas formal, não real", "A seguradora é concorrente direta da empresa"], "answer": 1}, {"q": "O que Simon sugere com a última fala?", "options": ["Que a diretoria se convence mais por riscos ao negócio do que por princípios éticos", "Que Nadia deve desistir da proposta", "Que ele pessoalmente não se importa com ética"], "answer": 0}, {"q": "Qual é a postura de Simon ao longo da conversa?", "options": ["Totalmente hostil às ideias de Nadia", "Entusiasmado e convencido desde o início", "Inicialmente resistente, mas pragmático e aberto a alternativas"], "answer": 2}]}, {"id": "dC2-6", "level": "C2", "title": "Not in My Park", "titlePt": "Não no meu parque", "setting": "Em uma reunião de bairro tensa, uma moradora confronta o representante de uma construtora sobre um novo prédio.", "speakers": [{"name": "Theresa", "g": "f"}, {"name": "Craig", "g": "m"}], "lines": [{"s": 1, "en": "If everyone could settle down for a moment. I know feelings are running high, but I'd like to walk you through what the development actually involves.", "pt": "Se todos pudessem se acalmar um pouco. Sei que os ânimos estão exaltados, mas gostaria de explicar o que o empreendimento de fato envolve."}, {"s": 0, "en": "With all due respect, we've seen the plans. Eight stories, right next to a park where our kids play. What's left to walk through?", "pt": "Com todo o respeito, já vimos as plantas. Oito andares, colado num parque onde nossos filhos brincam. O que mais há para explicar?"}, {"s": 1, "en": "Well, for starters, twenty percent of the units will be affordable housing. That's something this neighborhood has been asking for for years.", "pt": "Bom, para começar, vinte por cento das unidades serão habitação a preço acessível. É algo que este bairro pede há anos."}, {"s": 0, "en": "Twenty percent. And the other eighty will go for prices none of us could dream of paying. Let's not pretend this is charity.", "pt": "Vinte por cento. E os outros oitenta vão sair por preços que nenhum de nós sonharia em pagar. Não vamos fingir que isso é caridade."}, {"s": 1, "en": "Nobody's pretending it's charity. It's a business. But it's also more housing in a city that desperately needs it.", "pt": "Ninguém está fingindo que é caridade. É um negócio. Mas também é mais moradia numa cidade que precisa desesperadamente disso."}, {"s": 0, "en": "I'm not against housing. What I'm against is a building that'll cast a shadow over the only green space we've got for half the day.", "pt": "Não sou contra moradia. Sou contra um prédio que vai fazer sombra sobre a única área verde que temos durante metade do dia."}, {"s": 1, "en": "The shadow study shows the impact is limited to late afternoon in winter.", "pt": "O estudo de sombreamento mostra que o impacto se limita ao fim da tarde no inverno."}, {"s": 0, "en": "Commissioned by whom, exactly? Forgive me if I don't take your own study at face value.", "pt": "Encomendado por quem, exatamente? Me perdoe se eu não aceito o estudo de vocês sem questionar."}, {"s": 1, "en": "That's fair. If the neighborhood association wants an independent study, we'd be willing to cover the cost.", "pt": "É justo. Se a associação de moradores quiser um estudo independente, estamos dispostos a pagar por ele."}, {"s": 0, "en": "Now that's the first concrete thing I've heard tonight. Would you put that in writing?", "pt": "Bom, essa é a primeira coisa concreta que ouço esta noite. O senhor colocaria isso por escrito?"}, {"s": 1, "en": "I would. And I'll go further. If the independent study finds a significant impact, we'll look seriously at reducing the height.", "pt": "Colocaria. E vou além. Se o estudo independente encontrar um impacto significativo, vamos analisar seriamente a redução da altura."}, {"s": 0, "en": "Look seriously at. That's not quite the same as committing to it, is it?", "pt": "Analisar seriamente. Isso não é bem a mesma coisa que se comprometer, é?"}, {"s": 1, "en": "No, it isn't, and I won't promise what I can't deliver. But it's a genuine offer, not a talking point.", "pt": "Não, não é, e não vou prometer o que não posso cumprir. Mas é uma oferta sincera, não um discurso pronto."}, {"s": 0, "en": "Fine. Put it in writing, and we'll take it to the association. But don't mistake this for a yes.", "pt": "Tudo bem. Coloque por escrito e vamos levar à associação. Mas não confunda isso com um sim."}], "questions": [{"q": "Por que Theresa desconfia do estudo de sombreamento?", "options": ["Porque foi encomendado pela própria construtora", "Porque foi feito há muitos anos", "Porque não analisa o inverno"], "answer": 0}, {"q": "O que Theresa aponta ao repetir 'Look seriously at'?", "options": ["Que Craig prometeu reduzir a altura do prédio", "Que a expressão é vaga e não representa um compromisso real", "Que ela não entendeu a proposta"], "answer": 1}, {"q": "Qual é o resultado da conversa?", "options": ["Theresa aprova o projeto em nome da associação", "Craig retira o projeto", "Há um avanço concreto, mas Theresa deixa claro que ainda não concorda"], "answer": 2}]}, {"id": "dC2-7", "level": "C2", "title": "Fixing the Pitch", "titlePt": "Ajustando o pitch", "setting": "Dois sócios de uma startup de tecnologia agrícola reformulam a apresentação que farão para investidores.", "speakers": [{"name": "Maya", "g": "f"}, {"name": "Andre", "g": "m"}], "lines": [{"s": 0, "en": "Okay, the pitch is Thursday, and I'll be honest, our current deck is putting even me to sleep. And I wrote half of it.", "pt": "Tá, o pitch é na quinta e, vou ser sincera, nossa apresentação atual está fazendo até eu dormir. E eu escrevi metade dela."}, {"s": 1, "en": "Ha. Yeah, slide seven is basically a wall of text. What do you think the core problem is?", "pt": "Ha. É, o slide sete é basicamente um paredão de texto. Qual você acha que é o problema principal?"}, {"s": 0, "en": "We open with the technology. Investors don't care how clever our algorithm is until they care about the problem it solves.", "pt": "A gente começa pela tecnologia. Investidor não liga para o quanto o nosso algoritmo é inteligente até se importar com o problema que ele resolve."}, {"s": 1, "en": "So we lead with the pain point. The farmer losing a third of his harvest because he can't predict the frost.", "pt": "Então a gente começa pela dor. O agricultor que perde um terço da colheita porque não consegue prever a geada."}, {"s": 0, "en": "Exactly. Make it a person, not a statistic. Then hit them with the statistic once they're already invested, pun intended.", "pt": "Exatamente. Uma pessoa, não uma estatística. Aí a gente solta a estatística quando eles já estiverem envolvidos, ou melhor, investidos, com o perdão do trocadilho."}, {"s": 1, "en": "Groan. But yes. What about the numbers, though? Our traction is... modest, let's say.", "pt": "Que trocadilho horrível. Mas, sim. E os números? Nossa tração é... modesta, digamos."}, {"s": 0, "en": "Modest is generous. Which is exactly why we shouldn't hide it. What investors hate more than small numbers is founders who spin them.", "pt": "Modesta é ser generoso. Justamente por isso não devemos esconder. O que investidor detesta mais do que números pequenos é fundador que maquia os números."}, {"s": 1, "en": "Agreed. So we frame it as early but promising. Three pilot farms, all of which renewed. That's actually a strong signal.", "pt": "Concordo. Então apresentamos como algo inicial, mas promissor. Três fazendas piloto, e todas renovaram. Isso é, na verdade, um sinal forte."}, {"s": 0, "en": "It's our strongest card, if you ask me. A hundred percent retention, even on a tiny sample, says people actually need this.", "pt": "É a nossa carta mais forte, na minha opinião. Cem por cento de retenção, mesmo numa amostra minúscula, mostra que as pessoas realmente precisam disso."}, {"s": 1, "en": "Now, the valuation question. Not only do we need a number, we need to be able to defend it without flinching.", "pt": "Agora, a questão do valuation. Não só precisamos de um número, como precisamos conseguir defendê-lo sem vacilar."}, {"s": 0, "en": "Let's run through every hard question we can think of tomorrow. I'll play the skeptical investor. I'll be brutal.", "pt": "Amanhã vamos repassar todas as perguntas difíceis que conseguirmos imaginar. Eu faço o papel do investidor cético. Vou ser implacável."}, {"s": 1, "en": "You say that like it'll be a stretch for you.", "pt": "Você fala como se isso fosse exigir algum esforço da sua parte."}, {"s": 0, "en": "Careful. I can start being brutal right now, if you'd like.", "pt": "Cuidado. Posso começar a ser implacável agora mesmo, se você quiser."}], "questions": [{"q": "Segundo Maya, qual é o principal erro da apresentação atual?", "options": ["Ela é curta demais", "Começa pela tecnologia em vez do problema que ela resolve", "Não menciona a concorrência"], "answer": 1}, {"q": "Por que eles decidem não esconder os números modestos?", "options": ["Porque investidores desconfiam de fundadores que maquiam resultados", "Porque os números são, na verdade, excelentes", "Porque são obrigados por lei a divulgá-los"], "answer": 0}, {"q": "O que Andre insinua com 'You say that like it'll be a stretch for you'?", "options": ["Que Maya é tímida demais para fazer perguntas difíceis", "Que ele não quer ensaiar", "Que, de brincadeira, ser dura é algo natural para Maya"], "answer": 2}]}, {"id": "dC2-8", "level": "C2", "title": "The Red Line", "titlePt": "A linha vermelha", "setting": "Em uma galeria de arte, dois amigos discordam sobre uma obra minimalista muito comentada.", "speakers": [{"name": "Claire", "g": "f"}, {"name": "Oliver", "g": "m"}], "lines": [{"s": 1, "en": "So, this is the piece everyone's been raving about. A blank canvas with a single red line. I'm trying very hard to have an opinion.", "pt": "Então essa é a obra de que todo mundo anda falando maravilhas. Uma tela em branco com uma única linha vermelha. Estou me esforçando muito para ter uma opinião."}, {"s": 0, "en": "Look at it for more than five seconds before you dismiss it. Notice the line isn't actually straight. It wavers, ever so slightly.", "pt": "Olhe por mais de cinco segundos antes de descartar. Repare que a linha não é exatamente reta. Ela oscila, bem de leve."}, {"s": 1, "en": "It wavers. Right. And that's worth, what, the price of a small apartment?", "pt": "Ela oscila. Certo. E isso vale o quê, o preço de um apartamento pequeno?"}, {"s": 0, "en": "The price is a separate conversation, and frankly, a much less interesting one. What I find compelling is the tension.", "pt": "O preço é outra conversa e, francamente, bem menos interessante. O que me fascina é a tensão."}, {"s": 1, "en": "Tension. Between what and what? The paint and the wall?", "pt": "Tensão. Entre o quê e o quê? A tinta e a parede?"}, {"s": 0, "en": "Between control and failure. It's the artist trying to draw a perfect line by hand and not quite managing it. That's rather human, isn't it?", "pt": "Entre controle e fracasso. É a artista tentando traçar uma linha perfeita à mão e não conseguindo totalmente. Isso é bem humano, não é?"}, {"s": 1, "en": "Hm. When you put it like that, it's almost touching. Almost.", "pt": "Hum. Colocando dessa forma, é quase comovente. Quase."}, {"s": 0, "en": "See? You're coming around. What gets me is how much it asks of the viewer. It doesn't hand you anything.", "pt": "Viu? Você está mudando de ideia. O que me pega é o quanto ela exige de quem observa. Ela não te entrega nada de bandeja."}, {"s": 1, "en": "That's exactly my issue, though. If I need a twenty-minute explanation to appreciate it, has the art done its job, or have you?", "pt": "Mas é exatamente isso que me incomoda. Se eu preciso de uma explicação de vinte minutos para apreciá-la, quem fez o trabalho foi a arte ou foi você?"}, {"s": 0, "en": "Ooh, good question. I'd argue all art needs context. You didn't understand a sonnet the first time you read one either.", "pt": "Ah, boa pergunta. Eu diria que toda arte precisa de contexto. Você também não entendeu um soneto na primeira vez que leu um."}, {"s": 1, "en": "Fair, but nobody charges me a fortune to read a sonnet.", "pt": "Justo, mas ninguém me cobra uma fortuna para ler um soneto."}, {"s": 0, "en": "We're back to price. You're incorrigible.", "pt": "Voltamos ao preço. Você é incorrigível."}, {"s": 1, "en": "Guilty. Still, I'll concede one thing. I'm going to be thinking about that wobbly line all week, and I'm annoyed about it.", "pt": "Culpado. Mesmo assim, admito uma coisa. Vou passar a semana inteira pensando naquela linha torta, e isso me irrita."}, {"s": 0, "en": "Then I rest my case. That's precisely what good art does.", "pt": "Então não preciso dizer mais nada. É exatamente isso que a boa arte faz."}], "questions": [{"q": "Qual é a atitude inicial de Oliver em relação à obra?", "options": ["Ceticismo e um certo sarcasmo", "Admiração profunda", "Indiferença total, sem nenhum comentário"], "answer": 0}, {"q": "Segundo Claire, o que torna a obra interessante?", "options": ["O preço altíssimo", "A tensão entre controle e falha, algo muito humano", "O uso de cores vibrantes"], "answer": 1}, {"q": "Por que Claire diz 'I rest my case' no final?", "options": ["Porque Oliver admitiu que vai comprar a obra", "Porque ela desistiu de convencê-lo", "Porque Oliver admite que a obra o fez pensar, o que, para ela, prova o valor da arte"], "answer": 2}]}];
